import React from 'react';
import { useNavigate } from 'react-router-dom';
import { Button } from '../components/ui/button';
import { ArrowLeft, Construction } from 'lucide-react';

const ComingSoon = ({ title = 'Halaman' }) => {
  const navigate = useNavigate();

  return (
    <div className="flex items-center justify-center min-h-[60vh]">
      <div className="text-center space-y-6 max-w-md">
        <div className="mx-auto w-20 h-20 bg-gradient-to-br from-primary to-blue-600 rounded-2xl flex items-center justify-center shadow-lg">
          <Construction className="h-10 w-10 text-white" />
        </div>
        <div className="space-y-2">
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            {title}
          </h1>
          <p className="text-gray-600 dark:text-gray-400">
            Halaman ini sedang dalam pengembangan
          </p>
        </div>
        <Button
          onClick={() => navigate('/')}
          className="bg-gradient-to-r from-primary to-blue-600 hover:from-primary/90 hover:to-blue-700"
        >
          <ArrowLeft className="mr-2 h-4 w-4" />
          Kembali ke Dashboard
        </Button>
      </div>
    </div>
  );
};

export default ComingSoon;