import { useEffect, useState } from "react";

import { API_BASE_URL } from '@/config/api';
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { toast } from "@/components/ui/sonner";
import { useAuth } from "@/contexts/AuthContext";

export default function PembayaranIPL({ onPaymentSuccess }) {
  const [wargaList, setWargaList] = useState([]);
  const [selectedWarga, setSelectedWarga] = useState(null);
  const [unpaidBills, setUnpaidBills] = useState([]);
  const [selectedBills, setSelectedBills] = useState([]);
  const [metodePayar, setMetodeBayar] = useState("Tunai");
  const [keterangan, setKeterangan] = useState("");
  const [openDialog, setOpenDialog] = useState(false);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState("");
  const [paymentMode, setPaymentMode] = useState("TAGIHAN"); // TAGIHAN atau ADVANCE
  const [advanceNominal, setAdvanceNominal] = useState("");
  const { token, user } = useAuth();

  const loadWarga = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/warga`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await res.json();
      setWargaList(data.filter((w) => w.status === "active"));
    } catch (err) {
      console.error("Error loading warga:", err);
      toast.error("Gagal memuat data warga");
    }
  };

  const loadUnpaidBills = async (wargaId) => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/ipl/bills/${wargaId}/unpaid`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await res.json();
      setUnpaidBills(data);
      setSelectedBills([]);
    } catch (err) {
      console.error("Error loading bills:", err);
      toast.error("Gagal memuat tagihan");
    }
  };

  const handleSelectWarga = (warga) => {
    setSelectedWarga(warga);
    if (paymentMode === "TAGIHAN") {
      loadUnpaidBills(warga.id);
    }
    setOpenDialog(true);
  };

  const handleToggleBill = (monthKey) => {
    setSelectedBills((prev) =>
      prev.includes(monthKey) ? prev.filter((id) => id !== monthKey) : [...prev, monthKey]
    );
  };

  const handleSelectAll = () => {
    const availableMonthKeys = getAvailableMonths().map((m) => `${m.tahun}-${m.bulan}`);
    if (selectedBills.length === availableMonthKeys.length) {
      setSelectedBills([]);
    } else {
      setSelectedBills(availableMonthKeys);
    }
  };

  const processPembayaranTagihan = async () => {
    if (!selectedWarga || selectedBills.length === 0) {
      toast.error("Pilih warga dan minimal 1 tagihan");
      return;
    }

    const totalBayar = selectedBills.length * 325000;
    
    // Use actual bill IDs if available, otherwise use month keys (tahun-bulan format)
    const billIds = selectedBills.map((sb) => {
      const bill = unpaidBills.find((b) => `${b.tahun}-${b.bulan}` === sb);
      return bill ? bill.id : sb; // Use ID if found, otherwise use month key
    });

    setLoading(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/ipl/payment`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          warga_id: selectedWarga.id,
          bill_ids: billIds,
          total_bayar: totalBayar,
          metode_bayar: metodePayar,
          keterangan: keterangan || undefined,
        }),
      });

      if (!res.ok) throw new Error("Gagal proses pembayaran");

      const result = await res.json();
      toast.success("Pembayaran tagihan IPL berhasil diproses!");
      setOpenDialog(false);
      setSelectedWarga(null);
      setSelectedBills([]);
      setMetodeBayar("Tunai");
      setKeterangan("");
      onPaymentSuccess?.();
    } catch (err) {
      console.error("Error:", err);
      toast.error("Gagal proses pembayaran");
    } finally {
      setLoading(false);
    }
  };

  const processPembayaranAdvance = async () => {
    if (!selectedWarga) {
      toast.error("Pilih warga terlebih dahulu");
      return;
    }
    
    const nominalValue = parseFloat(advanceNominal);
    if (!advanceNominal || isNaN(nominalValue) || nominalValue <= 0) {
      toast.error("Masukkan nominal yang valid");
      return;
    }

    setLoading(true);
    try {
      console.log(`[DEBUG] Advance payment: warga=${selectedWarga.id}, nominal=${nominalValue}`);
      
      const res = await fetch(`${API_BASE_URL}/api/ipl/advance-payment`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          warga_id: selectedWarga.id,
          nominal: nominalValue,
          metode_bayar: metodePayar,
          keterangan: keterangan || undefined,
        }),
      });

      console.log(`[DEBUG] Response status: ${res.status}`);
      
      if (!res.ok) {
        const error = await res.json();
        console.error(`[ERROR] Server error: ${JSON.stringify(error)}`);
        throw new Error(error.detail || "Gagal proses pembayaran dimuka");
      }

      const result = await res.json();
      console.log(`[SUCCESS] Payment response: ${JSON.stringify(result)}`);
      
      toast.success("Pembayaran IPL dimuka berhasil diproses!");
      setOpenDialog(false);
      setSelectedWarga(null);
      setAdvanceNominal("");
      setMetodeBayar("Tunai");
      setKeterangan("");
      onPaymentSuccess?.();
    } catch (err) {
      console.error("Error:", err);
      toast.error(err.message || "Gagal proses pembayaran dimuka");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadWarga();
  }, []);

  const filteredWarga = wargaList.filter(
    (w) =>
      w.nama_lengkap.toLowerCase().includes(search.toLowerCase()) ||
      w.blok_rumah.toLowerCase().includes(search.toLowerCase())
  );

  const formatRupiah = (val) => {
    return new Intl.NumberFormat("id-ID", {
      style: "currency",
      currency: "IDR",
      minimumFractionDigits: 0,
    }).format(val);
  };

  const getMonthName = (month) => {
    const months = ["", "Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
    return months[month] || "";
  };

  const getNext12Months = () => {
    const currentYear = 2025;
    const months = [];
    
    for (let month = 1; month <= 12; month++) {
      months.push({ month, year: currentYear, label: `${getMonthName(month)} ${currentYear}` });
    }
    
    return months;
  };

  const getAvailableMonths = () => {
    const year2025Months = getNext12Months();
    
    const paidMonths = unpaidBills
      .filter((b) => b.status === "Lunas")
      .map((b) => `${b.tahun}-${b.bulan}`);
    
    return year2025Months
      .filter((m) => !paidMonths.includes(`${m.year}-${m.month}`))
      .map((m) => ({
        tahun: m.year,
        bulan: m.month,
        label: m.label,
        jumlah: 325000,
      }));
  };

  const totalBayar = selectedBills.length * 325000;

  return (
    <div className="space-y-4">
      {/* SEARCH */}
      <Input
        placeholder="Cari warga atau blok rumah..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        className="dark:bg-gray-800 dark:text-gray-100 dark:border-gray-700"
      />

      {/* WARGA LIST */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {filteredWarga.map((warga) => (
          <Card
            key={warga.id}
            className="p-4 cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-800 transition"
            onClick={() => handleSelectWarga(warga)}
          >
            <div className="flex justify-between items-start">
              <div>
                <h4 className="font-semibold dark:text-gray-100">{warga.nama_lengkap}</h4>
                <p className="text-sm text-gray-600 dark:text-gray-400">Blok {warga.blok_rumah}</p>
              </div>
              <Button size="sm" className="bg-primary hover:bg-primary/90 text-white">
                Bayar
              </Button>
            </div>
          </Card>
        ))}
      </div>

      {/* PAYMENT DIALOG */}
      <Dialog open={openDialog} onOpenChange={setOpenDialog}>
        <DialogContent className="max-w-sm dark:bg-gray-900 dark:text-gray-100 max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Pembayaran IPL</DialogTitle>
          </DialogHeader>

          {selectedWarga && (
            <div className="space-y-3">
              {/* WARGA INFO */}
              <div className="bg-gray-50 dark:bg-gray-800 p-3 rounded">
                <p className="font-semibold text-sm dark:text-gray-200">{selectedWarga.nama_lengkap}</p>
                <p className="text-xs text-gray-600 dark:text-gray-400">Blok {selectedWarga.blok_rumah}</p>
              </div>

              {/* MODE PEMBAYARAN */}
              <div className="space-y-2">
                <Label className="font-semibold text-sm">Mode Pembayaran</Label>
                <div className="space-y-1">
                  <div className="flex items-center gap-2">
                    <input
                      type="radio"
                      id="mode-tagihan"
                      name="mode"
                      value="TAGIHAN"
                      checked={paymentMode === "TAGIHAN"}
                      onChange={(e) => {
                        setPaymentMode(e.target.value);
                        setSelectedBills([]);
                        setAdvanceNominal("");
                        loadUnpaidBills(selectedWarga.id);
                      }}
                      className="cursor-pointer"
                    />
                    <label htmlFor="mode-tagihan" className="cursor-pointer text-xs dark:text-gray-300">
                      Bayar Tagihan IPL
                    </label>
                  </div>
                  <div className="flex items-center gap-2">
                    <input
                      type="radio"
                      id="mode-advance"
                      name="mode"
                      value="ADVANCE"
                      checked={paymentMode === "ADVANCE"}
                      onChange={(e) => {
                        setPaymentMode(e.target.value);
                        setSelectedBills([]);
                        setAdvanceNominal("");
                      }}
                      className="cursor-pointer"
                    />
                    <label htmlFor="mode-advance" className="cursor-pointer text-xs dark:text-gray-300">
                      Bayar Dimuka (Advance)
                    </label>
                  </div>
                </div>
              </div>

              {/* TAGIHAN MODE */}
              {paymentMode === "TAGIHAN" && (
                <>
                  <div className="space-y-1">
                    <div className="flex justify-between items-center gap-2">
                      <Label className="font-semibold text-sm">Tagihan (Max 12 bulan)</Label>
                      {getAvailableMonths().length > 0 && (
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={handleSelectAll}
                          className="text-xs h-7"
                        >
                          {selectedBills.length === getAvailableMonths().length ? "Hapus Semua" : "Pilih Semua"}
                        </Button>
                      )}
                    </div>

                    <div className="max-h-40 overflow-y-auto space-y-1 border rounded p-2 dark:border-gray-700 bg-gray-50 dark:bg-gray-800">
                      {getAvailableMonths().length === 0 ? (
                        <p className="text-xs text-gray-500 dark:text-gray-400">Tidak ada bulan tersedia</p>
                      ) : (
                        getAvailableMonths().map((month) => {
                          const monthKey = `${month.tahun}-${month.bulan}`;
                          return (
                            <div key={monthKey} className="flex items-center gap-2">
                              <Checkbox
                                checked={selectedBills.includes(monthKey)}
                                onCheckedChange={() => handleToggleBill(monthKey)}
                              />
                              <div className="flex-1 min-w-0">
                                <p className="text-xs font-semibold dark:text-gray-200 truncate">
                                  {month.label}
                                </p>
                                <p className="text-xs text-gray-600 dark:text-gray-400">
                                  {formatRupiah(month.jumlah)}
                                </p>
                              </div>
                            </div>
                          );
                        })
                      )}
                    </div>
                  </div>

                  {selectedBills.length > 0 && (
                    <div className="bg-blue-50 dark:bg-blue-900/20 p-2 rounded border border-blue-200 dark:border-blue-800">
                      <p className="text-xs text-blue-900 dark:text-blue-200">Total Pembayaran</p>
                      <p className="text-lg font-bold text-blue-600 dark:text-blue-400">
                        {formatRupiah(totalBayar)}
                      </p>
                    </div>
                  )}
                </>
              )}

              {/* ADVANCE MODE */}
              {paymentMode === "ADVANCE" && (
                <>
                  <div>
                    <Label className="font-semibold text-sm mb-1 block">Nominal Pembayaran</Label>
                    <Input
                      type="number"
                      placeholder="Nominal dimuka"
                      value={advanceNominal}
                      onChange={(e) => setAdvanceNominal(e.target.value)}
                      className="dark:bg-gray-800 dark:text-gray-100 dark:border-gray-700 text-sm h-8"
                      min="0"
                    />
                    {advanceNominal && (
                      <p className="text-xs text-gray-600 dark:text-gray-400 mt-1">
                        = {formatRupiah(parseFloat(advanceNominal) || 0)}
                      </p>
                    )}
                  </div>

                  {advanceNominal && parseFloat(advanceNominal) > 0 && (
                    <div className="bg-green-50 dark:bg-green-900/20 p-2 rounded border border-green-200 dark:border-green-800">
                      <p className="text-xs text-green-900 dark:text-green-200">Total Pembayaran</p>
                      <p className="text-lg font-bold text-green-600 dark:text-green-400">
                        {formatRupiah(parseFloat(advanceNominal))}
                      </p>
                    </div>
                  )}
                </>
              )}

              {/* METODE BAYAR */}
              <div className="space-y-1">
                <Label className="font-semibold text-sm mb-1 block">Metode Bayar</Label>
                <div className="space-y-1">
                  {["Tunai", "Transfer", "QRIS"].map((metode) => (
                    <div key={metode} className="flex items-center gap-2">
                      <input
                        type="radio"
                        id={metode}
                        name="metode"
                        value={metode}
                        checked={metodePayar === metode}
                        onChange={(e) => setMetodeBayar(e.target.value)}
                        className="cursor-pointer"
                      />
                      <label htmlFor={metode} className="cursor-pointer text-xs dark:text-gray-300">
                        {metode}
                      </label>
                    </div>
                  ))}
                </div>
              </div>

              {/* KETERANGAN */}
              <div>
                <Label className="font-semibold text-sm mb-1 block">Keterangan (Opsional)</Label>
                <Input
                  placeholder="Catatan..."
                  value={keterangan}
                  onChange={(e) => setKeterangan(e.target.value)}
                  className="dark:bg-gray-800 dark:text-gray-100 dark:border-gray-700 text-sm h-8"
                />
              </div>

              {/* ACTION */}
              <DialogFooter className="gap-2 pt-2">
                <Button
                  variant="outline"
                  onClick={() => setOpenDialog(false)}
                  className="dark:text-gray-200 text-sm h-8"
                >
                  Batal
                </Button>
                <Button
                  onClick={() => 
                    paymentMode === "TAGIHAN" 
                      ? processPembayaranTagihan() 
                      : processPembayaranAdvance()
                  }
                  disabled={
                    loading || 
                    (paymentMode === "TAGIHAN" && selectedBills.length === 0) ||
                    (paymentMode === "ADVANCE" && (!advanceNominal || parseFloat(advanceNominal) <= 0))
                  }
                  className="bg-primary hover:bg-primary/90 text-white text-sm h-8"
                >
                  {loading ? "Memproses..." : "Bayar"}
                </Button>
              </DialogFooter>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
}
