// Lapisan dekoratif untuk panel hero halaman login. Semua bentuk pakai warna
// putih/hitam tembus pandang (bukan warna tema langsung) supaya otomatis cocok
// di atas gradient primary/accent tema apapun yang sedang aktif - jadi "gaya
// latar" ini independen dari pilihan warna tema, keduanya bisa dikombinasikan.
const PATTERNS = {
  skyline: 'skyline',
  aurora: 'aurora',
  dots: 'dots',
};

function Skyline() {
  const lights = [18, 34, 47, 61, 76, 90];
  return (
    <>
      <svg
        className="absolute bottom-0 left-0 w-full h-[38%] text-black/25 dark:text-black/40"
        viewBox="0 0 400 140"
        preserveAspectRatio="none"
        fill="currentColor"
      >
        <rect x="0" y="70" width="40" height="70" />
        <rect x="36" y="40" width="34" height="100" />
        <polygon points="70,40 94,40 82,15" />
        <rect x="94" y="60" width="30" height="80" />
        <rect x="120" y="90" width="46" height="50" />
        <rect x="162" y="30" width="26" height="110" />
        <polygon points="162,30 188,30 175,8" />
        <rect x="188" y="75" width="50" height="65" />
        <rect x="234" y="50" width="30" height="90" />
        <rect x="260" y="95" width="40" height="45" />
        <rect x="296" y="35" width="28" height="105" />
        <polygon points="296,35 324,35 310,12" />
        <rect x="320" y="65" width="36" height="75" />
        <rect x="352" y="85" width="48" height="55" />
      </svg>
      {lights.map((left, i) => (
        <span
          key={i}
          className="absolute rounded-full bg-amber-300"
          style={{
            left: `${left}%`,
            bottom: `${10 + (i % 3) * 4}%`,
            width: 4,
            height: 4,
            boxShadow: '0 0 8px 2px rgba(252,211,77,0.85)',
            opacity: 0.9,
          }}
        />
      ))}
    </>
  );
}

function Aurora() {
  return (
    <>
      <div className="absolute -top-16 -left-16 w-72 h-72 rounded-full bg-white/10 blur-3xl" />
      <div className="absolute bottom-0 right-16 w-96 h-96 rounded-full bg-accent/30 blur-3xl" />
      <div className="absolute top-1/3 left-1/4 w-56 h-56 rounded-full bg-white/10 blur-3xl" />
    </>
  );
}

function Dots() {
  return (
    <div
      className="absolute inset-0 opacity-[0.15]"
      style={{
        backgroundImage: 'radial-gradient(rgba(255,255,255,0.9) 1.5px, transparent 1.5px)',
        backgroundSize: '22px 22px',
      }}
    />
  );
}

export default function LoginHeroBackground({ pattern = PATTERNS.skyline }) {
  if (pattern === PATTERNS.dots) return <Dots />;
  if (pattern === PATTERNS.aurora) return <Aurora />;
  return (
    <>
      <Aurora />
      <Skyline />
    </>
  );
}

export const HERO_PATTERNS = [
  { id: 'skyline', label: 'Siluet Gedung', description: 'Gedung + lampu hangat, senada gambar referensi' },
  { id: 'aurora', label: 'Aurora Lembut', description: 'Gradasi cahaya blur, minimalis' },
  { id: 'dots', label: 'Dot Grid', description: 'Pola titik halus, bersih & modern' },
];
