import { useEffect, useState } from "react";

import { API_BASE_URL } from "@/config/api";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { toast } from "@/components/ui/sonner";
import { useAuth } from "@/contexts/AuthContext";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

export default function WargaForm({ open, onOpenChange, warga, onSaved }) {
  const { token } = useAuth(); // 🔐 JWT
  const [loading, setLoading] = useState(false);
  const [rumahList, setRumahList] = useState([]); // 🏠 Rumah list for dropdown

  const [form, setForm] = useState({
    nama_lengkap: "",
    country_code: "+62",          // ✅ DEFAULT
    whatsapp: "",
    tanggal_lahir: "",
    jenis_kelamin: "Laki-laki",
    posisi_keluarga: "Kepala Keluarga",
    block_house: "",
    status: "active",
  });

  // --------------------------------------------------
  // HELPER: Format rumah display text
  // --------------------------------------------------
  const getDisplayText = (rumah) => {
    let text = rumah.blok_no;
    if (rumah.pemilik_sah) {
      text += ` - ${rumah.pemilik_sah}`;
    }
    if (rumah.nama_jalan) {
      text += ` (${rumah.nama_jalan})`;
    }
    return text;
  };

  // --------------------------------------------------
  // FETCH RUMAH LIST
  // --------------------------------------------------
  const fetchRumah = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/rumah`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.ok) {
        const data = await res.json();
        setRumahList(data);
      }
    } catch (err) {
      console.error("Gagal load rumah:", err);
    }
  };

  // --------------------------------------------------
  // LOAD DATA SAAT EDIT
  // --------------------------------------------------
  useEffect(() => {
    if (open) {
      fetchRumah();
    }
  }, [open]);

  // --------------------------------------------------
  // LOAD DATA SAAT EDIT
  // --------------------------------------------------
  useEffect(() => {
    if (warga && rumahList.length > 0) {
      // Find matching rumah to get formatted display text
      const matchingRumah = rumahList.find(r => r.blok_no === warga.block_house);
      const displayValue = matchingRumah ? getDisplayText(matchingRumah) : (warga.block_house || "");
      
      setForm({
        nama_lengkap: warga.nama_lengkap || "",
        country_code: warga.country_code || "+62",
        whatsapp: warga.whatsapp || "",
        tanggal_lahir: warga.tanggal_lahir ? warga.tanggal_lahir.split("T")[0] : "",
        jenis_kelamin: warga.jenis_kelamin || "Laki-laki",
        posisi_keluarga: warga.posisi_keluarga || "Kepala Keluarga",
        block_house: displayValue,
        status: warga.status || "active",
      });
    } else {
      setForm({
        nama_lengkap: "",
        country_code: "+62",
        whatsapp: "",
        tanggal_lahir: "",
        jenis_kelamin: "Laki-laki",
        posisi_keluarga: "Kepala Keluarga",
        block_house: "",
        status: "active",
      });
    }
  }, [warga, rumahList]);

  // --------------------------------------------------
  // SAVE
  // --------------------------------------------------
  const save = async () => {
    if (!form.nama_lengkap.trim()) {
      toast.error("Nama lengkap harus diisi");
      return;
    }

    if (!form.whatsapp.trim()) {
      toast.error("Nomor WhatsApp harus diisi");
      return;
    }

    setLoading(true);

    const url = warga
      ? `${API_BASE_URL}/api/warga/${warga.id}`
      : `${API_BASE_URL}/api/warga`;

    const method = warga ? "PUT" : "POST";

    try {
      // Convert empty strings to null untuk optional fields
      let blockHouseValue = form.block_house;
      
      // Extract blok_no from the full display text if it's not "none"
      if (blockHouseValue && blockHouseValue !== "none") {
        blockHouseValue = blockHouseValue.split(" - ")[0]; // Extract first part (blok_no)
      }
      
      const payload = {
        nama_lengkap: form.nama_lengkap || null,
        country_code: form.country_code,
        whatsapp: form.whatsapp || null,
        tanggal_lahir: form.tanggal_lahir ? form.tanggal_lahir : null,
        jenis_kelamin: form.jenis_kelamin || null,
        posisi_keluarga: form.posisi_keluarga || null,
        block_house: blockHouseValue === "none" ? null : (blockHouseValue || null),
        status: form.status,
      };

      const res = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`, // 🔐 JWT
        },
        body: JSON.stringify(payload),
      });

      if (!res.ok) {
        toast.error("Gagal menyimpan warga");
        setLoading(false);
        return;
      }

      toast.success(warga ? "Warga berhasil diperbarui!" : "Warga baru ditambahkan!");
      onSaved();
      onOpenChange(false);

    } catch (err) {
      toast.error("Tidak dapat terhubung ke server");
    }

    setLoading(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl dark:bg-gray-900 dark:text-gray-100 max-h-screen overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{warga ? "Edit Warga" : "Tambah Warga"}</DialogTitle>
        </DialogHeader>

        <div className="space-y-3">

          {/* ROW 1: NAMA LENGKAP */}
          <Input
            placeholder="Nama Lengkap"
            value={form.nama_lengkap}
            onChange={(e) =>
              setForm({ ...form, nama_lengkap: e.target.value })
            }
            className="dark:bg-gray-800 dark:text-gray-100"
          />

          {/* ROW 2: KODE NEGARA & WHATSAPP */}
          <div className="grid grid-cols-3 gap-3">
            <Input
              placeholder="Kode Negara"
              value={form.country_code}
              disabled
              className="dark:bg-gray-800 dark:text-gray-100"
            />
            <Input
              placeholder="Nomor WhatsApp"
              value={form.whatsapp}
              onChange={(e) =>
                setForm({ ...form, whatsapp: e.target.value })
              }
              className="col-span-2 dark:bg-gray-800 dark:text-gray-100"
            />
          </div>

          {/* ROW 3: TANGGAL LAHIR & JENIS KELAMIN */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                Tanggal Lahir
              </label>
              <Input
                type="date"
                value={form.tanggal_lahir}
                onChange={(e) =>
                  setForm({ ...form, tanggal_lahir: e.target.value })
                }
                className="dark:bg-gray-800 dark:text-gray-100"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                Jenis Kelamin
              </label>
              <select
                value={form.jenis_kelamin}
                onChange={(e) =>
                  setForm({ ...form, jenis_kelamin: e.target.value })
                }
                className="w-full p-2 rounded-md border
 border-gray-300 dark:border-gray-700
 bg-white dark:bg-gray-800
 text-gray-900 dark:text-gray-100
 focus:outline-none focus:ring-2 focus:ring-primary"
              >
                <option value="Laki-laki">Laki-laki</option>
                <option value="Perempuan">Perempuan</option>
              </select>
            </div>
          </div>

          {/* ROW 4: POSISI KELUARGA & BLOK / NO RUMAH */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                Posisi Keluarga
              </label>
              <select
                value={form.posisi_keluarga}
                onChange={(e) =>
                  setForm({ ...form, posisi_keluarga: e.target.value })
                }
                className="w-full p-2 rounded-md border
 border-gray-300 dark:border-gray-700
 bg-white dark:bg-gray-800
 text-gray-900 dark:text-gray-100
 focus:outline-none focus:ring-2 focus:ring-primary"
              >
                <option value="Kepala Keluarga">Kepala Keluarga</option>
                <option value="Istri">Istri</option>
                <option value="Anak">Anak</option>
                <option value="Lainnya">Lainnya</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                Blok / No Rumah
              </label>
              <Select value={form.block_house === "" ? "none" : form.block_house} onValueChange={(value) => {
                if (value === "none") {
                  setForm({ ...form, block_house: "none" });
                } else {
                  // Store the full display text, will extract blok_no when saving
                  setForm({ ...form, block_house: value });
                }
              }}>
                <SelectTrigger className="dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100">
                  <SelectValue placeholder="Pilih rumah" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">-- Tidak ada rumah --</SelectItem>
                  {rumahList.map((rumah) => {
                    const displayText = getDisplayText(rumah);
                    return (
                      <SelectItem key={rumah.id} value={displayText}>
                        {displayText}
                      </SelectItem>
                    );
                  })}
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* ROW 5: STATUS */}
          <div>
            <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
              Status
            </label>
            <select
              value={form.status}
              onChange={(e) =>
                setForm({ ...form, status: e.target.value })
              }
              className="w-full p-2 rounded-md border
 border-gray-300 dark:border-gray-700
 bg-white dark:bg-gray-800
 text-gray-900 dark:text-gray-100
 focus:outline-none focus:ring-2 focus:ring-primary"
            >
              <option value="active">Aktif</option>
              <option value="inactive">Tidak Aktif</option>
            </select>
          </div>

          {/* BUTTONS */}
          <div className="flex gap-3 justify-end pt-4">
            <Button
              variant="outline"
              onClick={() => onOpenChange(false)}
              className="dark:border-gray-700 dark:text-gray-200 dark:hover:bg-gray-800"
            >
              Batal
            </Button>
            <Button
              onClick={save}
              disabled={loading}
              className="bg-primary hover:bg-primary/90 text-white"
            >
              {loading ? "Menyimpan..." : "Simpan"}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}
