import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { COLOR_THEMES, DEFAULT_COLOR_THEME, DEFAULT_CUSTOM_COLORS, buildCustomThemeVars } from '../config/colorThemes';
import { API_BASE_URL, API_ENDPOINTS } from '../config/api';

const ThemeContext = createContext(null);

const CSS_VAR_MAP = {
  primary: '--primary',
  primaryDark: '--primary-dark',
  primaryForeground: '--primary-foreground',
  accent: '--accent',
  accentForeground: '--accent-foreground',
  ring: '--ring',
  background: '--background',
  card: '--card',
};

function applyColorVars(vars) {
  const root = document.documentElement;
  Object.entries(CSS_VAR_MAP).forEach(([key, cssVar]) => {
    if (vars[key]) {
      root.style.setProperty(cssVar, vars[key]);
    } else {
      // Preset mode ini (biasanya dark) sengaja tidak override token ini -
      // hapus inline style lama (kalau ada, dari mode/tema sebelumnya) supaya
      // nilai default dari index.css yang berlaku lagi, bukan nilai basi.
      root.style.removeProperty(cssVar);
    }
  });
}

const DEFAULT_HERO_PATTERN = 'skyline';

export const ThemeProvider = ({ children }) => {
  const [theme, setTheme] = useState('light');
  const [colorTheme, setColorThemeState] = useState(DEFAULT_COLOR_THEME);
  const [customColors, setCustomColorsState] = useState(DEFAULT_CUSTOM_COLORS);
  const [heroPattern, setHeroPatternState] = useState(DEFAULT_HERO_PATTERN);
  const [heroCustomBg, setHeroCustomBgState] = useState(null);

  // Latar foto custom DAN gaya pattern yang aktif (skyline/aurora/dots/custom)
  // disimpan di backend (bukan cuma localStorage) - berlaku untuk semua orang
  // yang buka halaman login dari perangkat manapun, bukan cuma browser yang
  // dipakai admin waktu mengatur.
  const refreshHeroCustomBg = useCallback(async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/login-background/public`);
      if (!res.ok) return;
      const data = await res.json();
      setHeroCustomBgState(data?.image_url || null);
      if (data?.pattern_id) {
        setHeroPatternState(data.pattern_id);
        localStorage.setItem('kbbs_hero_pattern', data.pattern_id);
      }
    } catch {
      // biarkan apa adanya (nilai localStorage lokal) - BrandPanel otomatis
      // fallback ke foto/pattern default kalau fetch gagal (mis. offline)
    }
  }, []);

  const applyColorTheme = useCallback((id, custom) => {
    if (id === 'custom') {
      applyColorVars(buildCustomThemeVars(custom || DEFAULT_CUSTOM_COLORS));
      return;
    }
    const preset = COLOR_THEMES[id] || COLOR_THEMES[DEFAULT_COLOR_THEME];
    const mode = document.documentElement.classList.contains('dark') ? 'dark' : 'light';
    applyColorVars(preset[mode]);
  }, []);

  useEffect(() => {
    const savedTheme = localStorage.getItem('rtpintar_theme') || 'light';
    setTheme(savedTheme);
    document.documentElement.classList.toggle('dark', savedTheme === 'dark');

    const savedColorTheme = localStorage.getItem('kbbs_color_theme') || DEFAULT_COLOR_THEME;
    const savedCustomRaw = localStorage.getItem('kbbs_custom_colors');
    const savedCustom = savedCustomRaw ? JSON.parse(savedCustomRaw) : DEFAULT_CUSTOM_COLORS;
    setColorThemeState(savedColorTheme);
    setCustomColorsState(savedCustom);
    applyColorTheme(savedColorTheme, savedCustom);

    const savedHeroPattern = localStorage.getItem('kbbs_hero_pattern') || DEFAULT_HERO_PATTERN;
    setHeroPatternState(savedHeroPattern);

    refreshHeroCustomBg();
  }, [applyColorTheme, refreshHeroCustomBg]);

  const toggleTheme = () => {
    const newTheme = theme === 'light' ? 'dark' : 'light';
    setTheme(newTheme);
    localStorage.setItem('rtpintar_theme', newTheme);
    document.documentElement.classList.toggle('dark', newTheme === 'dark');
    // Preset warna beda nilainya antara mode light/dark - re-apply supaya kontrasnya tetap pas.
    applyColorTheme(colorTheme, customColors);
  };

  const setColorTheme = (id) => {
    setColorThemeState(id);
    localStorage.setItem('kbbs_color_theme', id);
    applyColorTheme(id, customColors);
  };

  const setCustomColors = (colors) => {
    const merged = { ...customColors, ...colors };
    setCustomColorsState(merged);
    localStorage.setItem('kbbs_custom_colors', JSON.stringify(merged));
    if (colorTheme === 'custom') applyColorTheme('custom', merged);
  };

  const setHeroPattern = (id) => {
    setHeroPatternState(id);
    localStorage.setItem('kbbs_hero_pattern', id);
  };

  // Dipakai dari halaman Tema Tampilan saat admin memilih gaya latar login
  // (skyline/aurora/dots/custom) - persist ke server dulu (supaya berlaku
  // global untuk semua orang), baru update state lokal kalau berhasil.
  const setHeroPatternRemote = async (id) => {
    await API_ENDPOINTS.loginBackgroundSetPattern(id);
    setHeroPattern(id);
  };

  return (
    <ThemeContext.Provider
      value={{
        theme, toggleTheme,
        colorTheme, setColorTheme,
        customColors, setCustomColors,
        heroPattern, setHeroPattern, setHeroPatternRemote,
        heroCustomBg, refreshHeroCustomBg,
      }}
    >
      {children}
    </ThemeContext.Provider>
  );
};

export const useTheme = () => {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error('useTheme must be used within ThemeProvider');
  }
  return context;
};
