import { useEffect, useState } from "react";

import { API_BASE_URL } from "@/config/api";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { toast } from "@/components/ui/sonner";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Edit2, Trash2, Plus, Search } from "lucide-react";
import { useAuth } from "@/contexts/AuthContext";

// ====================================================
// UTILITIES
// ====================================================

const formatRupiah = (value) => {
  if (!value) return "";
  return value.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
};

const removeFormatting = (value) => {
  return value.replace(/\./g, "");
};

// ====================================================
// TARIF UMUM (SINGLE) SECTION
// ====================================================

function TarifUmumSection({ token }) {
  const [tarif, setTarif] = useState(null);
  const [nominal, setNominal] = useState("");
  const [aktif, setAktif] = useState(false);
  const [loading, setLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [showWarning, setShowWarning] = useState(false);
  const [pendingAktifState, setPendingAktifState] = useState(false);

  // Load tarif umum
  useEffect(() => {
    loadTarifUmum();
  }, []);

  const loadTarifUmum = async () => {
    try {
      setLoading(true);
      const res = await fetch(`${API_BASE_URL}/api/tarif-ipl/single`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (res.ok) {
        const data = await res.json();
        setTarif(data);
        setNominal(data.nominal.toString());
        setAktif(data.aktif);
      }
    } catch (err) {
      console.error("Error loading tarif umum:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleAktifChange = (newState) => {
    // If enabling SINGLE, show warning that CUSTOM will be deactivated
    if (newState && !aktif) {
      setShowWarning(true);
      setPendingAktifState(newState);
    } else {
      setAktif(newState);
    }
  };

  const handleConfirmAktif = () => {
    setAktif(pendingAktifState);
    setShowWarning(false);
  };

  const handleSave = async () => {
    // Validation: nominal bisa 0 (akan set status tidak aktif otomatis)
    // Hanya perlu ada input nominal
    if (nominal === "" || nominal === undefined) {
      toast.error("Nominal harus diisi");
      return;
    }

    // If nominal 0, force aktif = false
    const finalAktif = parseFloat(nominal) > 0 ? aktif : false;

    try {
      setIsSaving(true);
      const res = await fetch(`${API_BASE_URL}/api/tarif-ipl/single`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          tipe_tarif: "SINGLE",
          nominal: parseFloat(nominal),
          aktif: finalAktif,
        }),
      });

      if (res.ok) {
        const data = await res.json();
        setTarif(data);
        setAktif(data.aktif); // Update UI status sesuai response
        toast.success("Tarif Umum berhasil disimpan");
      } else {
        const err = await res.json();
        toast.error(err.detail || "Gagal menyimpan tarif");
      }
    } catch (err) {
      console.error("Error saving tarif umum:", err);
      toast.error("Terjadi kesalahan");
    } finally {
      setIsSaving(false);
    }
  };

  if (loading) {
    return <div className="p-6 text-gray-500">Memuat...</div>;
  }

  return (
    <>
      <div className="bg-white dark:bg-gray-800 rounded-lg p-6 border border-gray-200 dark:border-gray-700">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          💰 Tarif Umum (SINGLE)
        </h3>

        <div className="space-y-4">
          <div>
            <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">
              Nominal IPL (Rp)
            </Label>
            <Input
              type="text"
              placeholder="0"
              value={formatRupiah(nominal)}
              onChange={(e) => setNominal(removeFormatting(e.target.value))}
              className="mt-2 dark:bg-gray-700 dark:text-white dark:border-gray-600"
            />
          </div>

          <div className="flex items-center space-x-2">
            <Checkbox
              id="aktif-single"
              checked={aktif}
              onCheckedChange={handleAktifChange}
            />
            <Label
              htmlFor="aktif-single"
              className="text-sm font-medium text-gray-700 dark:text-gray-300 cursor-pointer"
            >
              Status Aktif
            </Label>
          </div>

          <Button
            onClick={handleSave}
            disabled={isSaving}
            className="w-full bg-blue-600 hover:bg-blue-700 text-white"
          >
            {isSaving ? "Menyimpan..." : "💾 Simpan Tarif Umum"}
          </Button>
        </div>
      </div>

      {/* Warning Dialog */}
      <AlertDialog open={showWarning} onOpenChange={setShowWarning}>
        <AlertDialogContent className="dark:bg-gray-800">
          <AlertDialogHeader>
            <AlertDialogTitle className="dark:text-white">Aktifkan Tarif Umum?</AlertDialogTitle>
            <AlertDialogDescription className="dark:text-gray-400">
              Mengaktifkan Tarif Umum (SINGLE) akan otomatis menonaktifkan semua Tarif Khusus (CUSTOM) yang aktif. Lanjutkan?
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="dark:border-gray-600 dark:text-white">Batal</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleConfirmAktif}
              className="bg-blue-600 hover:bg-blue-700 text-white"
            >
              Lanjutkan
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

// ====================================================
// TARIF KHUSUS (CUSTOM) SECTION
// ====================================================

function TarifKhususModal({ open, onOpenChange, tarif, rumahList, onSaved, token }) {
  const [form, setForm] = useState({
    rumah_id: "",
    nominal: "",
    aktif: true,
  });
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (tarif) {
      setForm({
        rumah_id: tarif.rumah_id,
        nominal: tarif.nominal.toString(),
        aktif: tarif.aktif,
      });
    } else {
      setForm({
        rumah_id: "",
        nominal: "",
        aktif: true,
      });
    }
  }, [tarif, open]);

  const handleSave = async () => {
    // Validation: hanya cek rumah_id untuk CREATE mode
    if (!tarif && !form.rumah_id) {
      toast.error("Pilih rumah terlebih dahulu");
      return;
    }

    if (!form.nominal || parseFloat(form.nominal) <= 0) {
      toast.error("Nominal harus lebih dari 0");
      return;
    }

    try {
      setLoading(true);
      const url = tarif
        ? `${API_BASE_URL}/api/tarif-ipl/custom/${tarif.id}`
        : `${API_BASE_URL}/api/tarif-ipl/custom`;

      const method = tarif ? "PUT" : "POST";

      const payload = tarif
        ? {
            nominal: parseFloat(form.nominal),
            aktif: form.aktif,
          }
        : {
            tipe_tarif: "CUSTOM",
            rumah_id: form.rumah_id,
            nominal: parseFloat(form.nominal),
            aktif: form.aktif,
          };

      console.log("Sending request:", { method, url, payload });

      const res = await fetch(url, {
        method: method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(payload),
      });

      if (res.ok) {
        toast.success(tarif ? "Tarif berhasil diupdate" : "Tarif berhasil ditambah");
        onSaved();
        onOpenChange(false);
      } else {
        try {
          const err = await res.json();
          toast.error(err.detail || "Gagal menyimpan tarif");
        } catch (parseErr) {
          toast.error(`Gagal menyimpan tarif (HTTP ${res.status})`);
        }
      }
    } catch (err) {
      console.error("Error saving tarif custom:", err);
      const errorMsg = err instanceof TypeError 
        ? "Tidak dapat terhubung ke server - pastikan backend berjalan"
        : err.message || "Gagal menyimpan tarif";
      toast.error("Terjadi kesalahan: " + errorMsg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md dark:bg-gray-800">
        <DialogHeader>
          <DialogTitle className="dark:text-white">
            {tarif ? "Edit Tarif Khusus" : "Tambah Tarif Khusus"}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          <div>
            <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">
              Pilih Rumah / Warga {tarif && "(Tidak bisa diubah)"}
            </Label>
            {tarif ? (
              <div className="mt-2 p-2 bg-gray-100 dark:bg-gray-600 rounded border border-gray-300 dark:border-gray-500 text-gray-900 dark:text-white">
                {rumahList.find((r) => r.id === form.rumah_id)?.nama_lengkap ||
                  rumahList.find((r) => r.id === form.rumah_id)?.pemilik_sah ||
                  "Unknown"} ({rumahList.find((r) => r.id === form.rumah_id)?.blok_no})
              </div>
            ) : (
              <Select value={form.rumah_id} onValueChange={(val) => setForm({ ...form, rumah_id: val })}>
                <SelectTrigger className="mt-2 dark:bg-gray-700 dark:text-white dark:border-gray-600">
                  <SelectValue placeholder="Pilih rumah..." />
                </SelectTrigger>
                <SelectContent className="dark:bg-gray-700">
                  {rumahList.map((r) => (
                    <SelectItem key={r.id} value={r.id} className="dark:text-white">
                      {r.nama_lengkap || r.pemilik_sah || "Unknown"} ({r.blok_no})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            )}
          </div>

          <div>
            <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">
              Nominal IPL (Rp)
            </Label>
            <Input
              type="text"
              placeholder="0"
              value={formatRupiah(form.nominal)}
              onChange={(e) => setForm({ ...form, nominal: removeFormatting(e.target.value) })}
              className="mt-2 dark:bg-gray-700 dark:text-white dark:border-gray-600"
            />
          </div>

          <div className="flex items-center space-x-2">
            <Checkbox
              id="aktif-custom"
              checked={form.aktif}
              onCheckedChange={(val) => setForm({ ...form, aktif: val })}
            />
            <Label
              htmlFor="aktif-custom"
              className="text-sm font-medium text-gray-700 dark:text-gray-300 cursor-pointer"
            >
              Status Aktif
            </Label>
          </div>
        </div>

        <div className="flex gap-2 justify-end pt-4">
          <Button variant="outline" onClick={() => onOpenChange(false)} className="dark:border-gray-600">
            Batal
          </Button>
          <Button onClick={handleSave} disabled={loading} className="bg-blue-600 hover:bg-blue-700 text-white">
            {loading ? "Menyimpan..." : "Simpan"}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

// ====================================================
// DELETE CONFIRMATION
// ====================================================

function DeleteConfirmDialog({ open, onOpenChange, onConfirm, loading }) {
  return (
    <AlertDialog open={open} onOpenChange={onOpenChange}>
      <AlertDialogContent className="dark:bg-gray-800">
        <AlertDialogHeader>
          <AlertDialogTitle className="dark:text-white">Hapus Tarif Khusus?</AlertDialogTitle>
          <AlertDialogDescription className="dark:text-gray-400">
            Tindakan ini tidak dapat dibatalkan. Warga akan kembali menggunakan tarif umum.
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel className="dark:border-gray-600 dark:text-white">Batal</AlertDialogCancel>
          <AlertDialogAction
            onClick={onConfirm}
            disabled={loading}
            className="bg-red-600 hover:bg-red-700 text-white"
          >
            {loading ? "Menghapus..." : "Hapus"}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

// ====================================================
// MAIN COMPONENT
// ====================================================

export default function TarifIPLPage() {
  const { token } = useAuth();
  const [rumahList, setRumahList] = useState([]);
  const [tarifCustom, setTarifCustom] = useState([]);
  const [searchWarga, setSearchWarga] = useState("");
  const [filterStatus, setFilterStatus] = useState("semua");
  const [loading, setLoading] = useState(false);
  
  // Pagination
  const [pageSize, setPageSize] = useState(10);
  const [currentPage, setCurrentPage] = useState(0);
  const [totalTarif, setTotalTarif] = useState(0);

  // Modal & Dialog
  const [openFormModal, setOpenFormModal] = useState(false);
  const [selectedTarif, setSelectedTarif] = useState(null);
  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);
  const [deleteTargetId, setDeleteTargetId] = useState(null);
  const [deleting, setDeleting] = useState(false);

  // Load data
  useEffect(() => {
    loadRumah();
    loadTarifCustom();
  }, []);

  // Reload when page or pageSize changes
  useEffect(() => {
    loadTarifCustom();
  }, [currentPage, pageSize]);

  const loadRumah = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/rumah`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (res.ok) {
        const data = await res.json();
        // Filter active rumah only (all rumah, not just those with warga assigned)
        setRumahList(data.filter((r) => r.aktif));
      }
    } catch (err) {
      console.error("Error loading warga:", err);
    }
  };

  const loadTarifCustom = async () => {
    try {
      setLoading(true);
      const skip = currentPage * pageSize;
      const res = await fetch(
        `${API_BASE_URL}/api/tarif-ipl/custom?skip=${skip}&limit=${pageSize}`,
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );

      if (res.ok) {
        const responseData = await res.json();
        // Handle both old format (array) and new format (object with data, total)
        if (Array.isArray(responseData)) {
          setTarifCustom(responseData);
          setTotalTarif(responseData.length);
        } else {
          setTarifCustom(responseData.data || []);
          setTotalTarif(responseData.total || 0);
        }
      }
    } catch (err) {
      console.error("Error loading tarif custom:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleAddTarif = () => {
    setSelectedTarif(null);
    setOpenFormModal(true);
  };

  const handleEditTarif = (tarif) => {
    setSelectedTarif(tarif);
    setOpenFormModal(true);
  };

  const handleDeleteConfirm = (tarifId) => {
    setDeleteTargetId(tarifId);
    setDeleteConfirmOpen(true);
  };

  const handleDeleteTarif = async () => {
    if (!deleteTargetId) return;

    try {
      setDeleting(true);
      const res = await fetch(
        `${API_BASE_URL}/api/tarif-ipl/custom/${deleteTargetId}`,
        {
          method: "DELETE",
          headers: { Authorization: `Bearer ${token}` },
        }
      );

      if (res.ok) {
        toast.success("Tarif berhasil dihapus");
        loadTarifCustom();
        setDeleteConfirmOpen(false);
        setDeleteTargetId(null);
      } else {
        try {
          const err = await res.json();
          toast.error(err.detail || "Gagal menghapus tarif");
        } catch (parseErr) {
          toast.error(`Gagal menghapus tarif (HTTP ${res.status})`);
        }
      }
    } catch (err) {
      console.error("Error deleting tarif:", err);
      toast.error("Terjadi kesalahan: " + (err.message || "Gagal menghapus tarif"));
    } finally {
      setDeleting(false);
    }
  };

  // Filter & search
  const filteredTarif = tarifCustom.filter((t) => {
    const rumah = rumahList.find((r) => r.id === t.rumah_id);
    const rumahName = rumah?.nama_lengkap || rumah?.pemilik_sah || "Unknown";
    const matchSearch = rumahName
      .toLowerCase()
      .includes(searchWarga.toLowerCase());
    const matchStatus =
      filterStatus === "semua" ||
      (filterStatus === "aktif" && t.aktif) ||
      (filterStatus === "nonaktif" && !t.aktif);

    return matchSearch && matchStatus;
  });

  return (
    <div className="space-y-6 p-6 bg-gray-50 dark:bg-gray-900 min-h-screen">
      <div>
        <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
          ⚙️ Konfigurasi Tarif IPL
        </h1>
        <p className="text-gray-600 dark:text-gray-400 mt-1">
          Atur tarif IPL umum dan tarif khusus per warga
        </p>
      </div>

      {/* SECTION 1: TARIF UMUM */}
      <TarifUmumSection token={token} />

      {/* SECTION 2: TARIF KHUSUS */}
      <div className="bg-white dark:bg-gray-800 rounded-lg p-6 border border-gray-200 dark:border-gray-700">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
            👤 Tarif Khusus Warga (CUSTOM)
          </h3>
          <Button
            onClick={handleAddTarif}
            className="gap-2 bg-green-600 hover:bg-green-700 text-white"
          >
            <Plus className="h-4 w-4" />
            Tambah Tarif Khusus
          </Button>
        </div>

        {/* Search & Filter */}
        <div className="flex gap-3 mb-4">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-2.5 h-4 w-4 text-gray-400" />
            <Input
              placeholder="Cari nama warga..."
              value={searchWarga}
              onChange={(e) => setSearchWarga(e.target.value)}
              className="pl-10 dark:bg-gray-700 dark:text-white dark:border-gray-600"
            />
          </div>
          <Select value={filterStatus} onValueChange={setFilterStatus}>
            <SelectTrigger className="w-48 dark:bg-gray-700 dark:text-white dark:border-gray-600">
              <SelectValue />
            </SelectTrigger>
            <SelectContent className="dark:bg-gray-700">
              <SelectItem value="semua" className="dark:text-white">Semua Status</SelectItem>
              <SelectItem value="aktif" className="dark:text-white">Aktif</SelectItem>
              <SelectItem value="nonaktif" className="dark:text-white">Non-aktif</SelectItem>
            </SelectContent>
          </Select>
          
          {/* Page Size Selector */}
          <Select value={pageSize.toString()} onValueChange={(val) => {
            setPageSize(parseInt(val));
            setCurrentPage(0);
          }}>
            <SelectTrigger className="w-24 dark:bg-gray-700 dark:text-white dark:border-gray-600">
              <SelectValue />
            </SelectTrigger>
            <SelectContent className="dark:bg-gray-700">
              <SelectItem value="10" className="dark:text-white">10 per halaman</SelectItem>
              <SelectItem value="25" className="dark:text-white">25 per halaman</SelectItem>
              <SelectItem value="50" className="dark:text-white">50 per halaman</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* Table */}
        {loading ? (
          <div className="text-center py-8 text-gray-500">Memuat...</div>
        ) : filteredTarif.length === 0 ? (
          <div className="text-center py-8 text-gray-500">Belum ada tarif khusus</div>
        ) : (
          <>
            <Table>
              <TableHeader>
                <TableRow className="border-gray-200 dark:border-gray-700">
                  <TableHead className="text-gray-700 dark:text-gray-300">Warga</TableHead>
                  <TableHead className="text-gray-700 dark:text-gray-300">Rumah</TableHead>
                  <TableHead className="text-gray-700 dark:text-gray-300">Nominal</TableHead>
                  <TableHead className="text-gray-700 dark:text-gray-300">Status</TableHead>
                  <TableHead className="text-right text-gray-700 dark:text-gray-300">Aksi</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredTarif.map((t) => {
                  const rumah = rumahList.find((r) => r.id === t.rumah_id);
                  return (
                    <TableRow key={t.id} className="border-gray-200 dark:border-gray-700">
                      <TableCell className="text-gray-900 dark:text-white">
                        {rumah?.nama_lengkap || rumah?.pemilik_sah || "Unknown"}
                      </TableCell>
                      <TableCell className="text-gray-600 dark:text-gray-400">
                        {rumah?.blok_no || "-"}
                      </TableCell>
                      <TableCell className="text-gray-900 dark:text-white font-medium">
                        Rp {formatRupiah(t.nominal)}
                      </TableCell>
                      <TableCell>
                        <span
                          className={`px-3 py-1 rounded-full text-xs font-medium ${
                            t.aktif
                              ? "bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200"
                              : "bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-400"
                          }`}
                        >
                          {t.aktif ? "Aktif" : "Non-aktif"}
                        </span>
                      </TableCell>
                      <TableCell className="text-right">
                        <div className="flex justify-end gap-2">
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => handleEditTarif(t)}
                            className="dark:border-gray-600 dark:text-white"
                          >
                            <Edit2 className="h-4 w-4" />
                          </Button>
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => handleDeleteConfirm(t.id)}
                            className="dark:border-gray-600 dark:text-red-400 text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20"
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
            
            {/* Pagination */}
            <div className="flex items-center justify-between mt-4 pt-4 border-t border-gray-200 dark:border-gray-700">
              <div className="text-sm text-gray-600 dark:text-gray-400">
                Menampilkan {currentPage * pageSize + 1} - {Math.min((currentPage + 1) * pageSize, totalTarif)} dari {totalTarif} data
              </div>
              
              <div className="flex gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setCurrentPage(Math.max(0, currentPage - 1))}
                  disabled={currentPage === 0}
                  className="dark:border-gray-600 dark:text-white"
                >
                  ← Sebelumnya
                </Button>
                
                <div className="flex items-center gap-1">
                  <span className="text-sm text-gray-600 dark:text-gray-400">
                    Halaman {currentPage + 1}
                  </span>
                </div>
                
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setCurrentPage(currentPage + 1)}
                  disabled={(currentPage + 1) * pageSize >= totalTarif}
                  className="dark:border-gray-600 dark:text-white"
                >
                  Berikutnya →
                </Button>
              </div>
            </div>
          </>
        )}
      </div>

      {/* MODALS */}
      <TarifKhususModal
        open={openFormModal}
        onOpenChange={setOpenFormModal}
        tarif={selectedTarif}
        rumahList={rumahList}
        onSaved={loadTarifCustom}
        token={token}
      />

      <DeleteConfirmDialog
        open={deleteConfirmOpen}
        onOpenChange={setDeleteConfirmOpen}
        onConfirm={handleDeleteTarif}
        loading={deleting}
      />
    </div>
  );
}
