import React, { useState } from 'react';
import { API_BASE_URL } from '../config/api';
import { Button } from '../components/ui/button';
import { Input } from '../components/ui/input';
import { Label } from '../components/ui/label';
import { Smartphone, MessageCircle, CheckCircle2, XCircle, ArrowRight, Info } from 'lucide-react';
import { useTheme } from '../contexts/ThemeContext';
import BrandPanel from '../components/BrandPanel';

const BotVerificationPage = () => {
  const { heroPattern, heroCustomBg } = useTheme();

  const [phone, setPhone] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  // result: null | { status: 'success' | 'partial' | 'failed', message: string, nama?: string }
  const [result, setResult] = useState(null);

  const inputClass =
    "pl-12 h-11 sm:h-14 bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 rounded-xl text-[15px] " +
    "focus:ring-4 focus:ring-primary/10 focus:border-primary transition-all duration-200";
  const buttonClass =
    "w-full h-11 sm:h-14 bg-primary hover:bg-primary/90 text-primary-foreground font-semibold text-base rounded-xl " +
    "shadow-lg shadow-primary/25 transition-all duration-200 hover:-translate-y-0.5 hover:shadow-xl hover:shadow-primary/30 " +
    "active:translate-y-0 active:shadow-md flex items-center justify-center gap-2 disabled:hover:translate-y-0";

  const handleSubmit = async (e) => {
    e.preventDefault();
    setResult(null);

    const digits = phone.replace(/\D/g, '');
    if (digits.length < 9) {
      setResult({ status: 'failed', message: 'Masukkan nomor WhatsApp yang valid (diawali angka 0).' });
      return;
    }

    setIsLoading(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/akses-bot/verify`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ whatsapp: phone }),
      });

      const text = await res.text();
      let data = {};
      try {
        data = JSON.parse(text);
      } catch (err) {
        data = {};
      }

      if (!res.ok) {
        setResult({ status: 'failed', message: data.detail || 'Terjadi kesalahan, silakan coba lagi.' });
        return;
      }

      if (!data.terdaftar) {
        setResult({ status: 'failed', message: data.message });
      } else if (data.wa_terkirim) {
        setResult({ status: 'success', message: data.message, nama: data.nama });
      } else {
        setResult({ status: 'partial', message: data.message, nama: data.nama });
      }
    } catch (err) {
      console.error('Verify bot error:', err);
      setResult({ status: 'failed', message: 'Tidak dapat terhubung ke server. Silakan coba lagi.' });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="h-dvh md:h-auto md:min-h-screen w-full flex flex-col md:flex-row overflow-hidden md:overflow-x-hidden bg-white dark:bg-gray-900">
      {/* Brand Panel - top on mobile, left on tablet/desktop */}
      <div className="md:hidden flex-shrink-0 animate-fade-slide-up">
        <BrandPanel heroPattern={heroPattern} heroCustomBg={heroCustomBg} variant="top" />
      </div>
      <div className="hidden md:block md:w-1/2 animate-fade-slide-left">
        <BrandPanel heroPattern={heroPattern} heroCustomBg={heroCustomBg} variant="side" />
      </div>

      {/* Form Panel */}
      <div className="flex-1 min-h-0 flex items-center justify-center px-5 py-3 sm:px-10 sm:py-10 lg:px-16 bg-white dark:bg-gray-900 overflow-y-auto">
        <div className="w-full max-w-[440px] animate-fade-slide-right">
          <div>
            <p className="flex items-center gap-1.5 text-xs sm:text-sm font-semibold text-primary mb-1 sm:mb-2">
              <MessageCircle className="h-3.5 w-3.5 sm:h-4 sm:w-4 text-accent" />
              Asisten KBBS via WhatsApp
            </p>
            <h2 className="text-xl sm:text-[26px] lg:text-[28px] font-bold text-[#12332F] dark:text-white tracking-tight leading-[1.15]">
              Verifikasi Nomor WhatsApp
            </h2>
            <p className="mt-1 sm:mt-2 text-xs sm:text-sm text-[#71807D] dark:text-gray-400">
              Hubungkan nomor WhatsApp Anda agar bisa chat dengan Asisten KBBS
            </p>
          </div>

          <div className="mt-3 sm:mt-8">
            <form onSubmit={handleSubmit} className="space-y-2.5 sm:space-y-5">
              <div className="space-y-1 sm:space-y-2">
                <Label htmlFor="bot-phone" className="text-[#12332F] dark:text-gray-300 text-sm font-medium">
                  No WhatsApp
                </Label>
                <div className="relative">
                  <Smartphone className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                  <Input
                    id="bot-phone"
                    type="tel"
                    placeholder="08xxxxxxxxxx"
                    value={phone}
                    onChange={(e) => setPhone(e.target.value)}
                    className={inputClass}
                    disabled={isLoading}
                    autoComplete="tel"
                    autoFocus
                  />
                </div>

                {/* Keterangan / hint */}
                <div className="flex items-start gap-2 pt-1">
                  <Info className="h-4 w-4 text-primary/70 flex-shrink-0 mt-0.5" />
                  <p className="text-xs text-[#71807D] dark:text-gray-400 leading-relaxed">
                    Gunakan nomor WhatsApp yang sama seperti data warga / rumah agar dapat
                    diverifikasi oleh pengurus KBBS. Contoh format: <span className="font-medium text-[#12332F] dark:text-gray-300">08xxxxxxxxxx</span> (diawali angka 0).
                  </p>
                </div>
              </div>

              {result && result.status === 'success' && (
                <div className="flex items-start gap-2 p-3 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 rounded-xl text-green-700 dark:text-green-400">
                  <CheckCircle2 className="h-4 w-4 flex-shrink-0 mt-0.5" />
                  <p className="text-sm">{result.message}</p>
                </div>
              )}

              {result && result.status === 'partial' && (
                <div className="flex items-start gap-2 p-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-xl text-amber-700 dark:text-amber-400">
                  <Info className="h-4 w-4 flex-shrink-0 mt-0.5" />
                  <p className="text-sm">{result.message}</p>
                </div>
              )}

              {result && result.status === 'failed' && (
                <div className="flex items-start gap-2 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl text-red-600 dark:text-red-400">
                  <XCircle className="h-4 w-4 flex-shrink-0 mt-0.5" />
                  <p className="text-sm">{result.message}</p>
                </div>
              )}

              <Button type="submit" className={buttonClass} disabled={isLoading}>
                {isLoading ? (
                  'Memverifikasi...'
                ) : (
                  <>
                    Verifikasi Sekarang <ArrowRight className="h-4 w-4" />
                  </>
                )}
              </Button>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
};

export default BotVerificationPage;
