import { useEffect, useState } from "react";

import { API_BASE_URL } from "@/config/api";
import { useLocation } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import RumahTable from "./RumahTable";
import RumahFormModal from "./RumahFormModal";
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogCancel,
  AlertDialogAction
} from "@/components/ui/alert-dialog";
import * as XLSX from "xlsx";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "@/components/ui/sonner";
import { useRolePermissions } from "@/hooks/useRolePermissions";

export default function RumahPage() {
  const location = useLocation();
  const [rumahList, setRumahList] = useState([]);
  const [search, setSearch] = useState("");
  const { token, logout, user } = useAuth();
  const { canCreate, canDelete } = useRolePermissions(user?.role, token);

  // FORM
  const [openForm, setOpenForm] = useState(false);
  const [selectedRumah, setSelectedRumah] = useState(null);

  // MULTI SELECT
  const [selectedRows, setSelectedRows] = useState([]);

  // FILTER
  const [showFilter, setShowFilter] = useState(false);
  const [filterJenisPemilik, setFilterJenisPemilik] = useState("all");
  const [filterStatusPenghuni, setFilterStatusPenghuni] = useState("all");
  const [filterKosong, setFilterKosong] = useState("all");

  // PAGINATION
  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(10);

  // BULK DELETE DIALOG
  const [openBulkDelete, setOpenBulkDelete] = useState(false);

  // Load rumah list
  const loadRumah = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/rumah`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.status === 401) {
        logout();
        return;
      }

      const data = await res.json();
      setRumahList(data);
    } catch (err) {
      console.error("Gagal load rumah", err);
      toast.error("Gagal memuat data rumah");
    }
  };

  useEffect(() => {
    loadRumah();
  }, []);

  // Auto-search dari state (misal dari IPL page)
  useEffect(() => {
    if (location.state?.searchBlok) {
      setSearch(location.state.searchBlok);
    }
  }, [location.state?.searchBlok]);

  // FILTER LOGIC
  const filtered = rumahList
    .filter((r) =>
      r.blok_no.toLowerCase().includes(search.toLowerCase()) ||
      (r.nama_jalan && r.nama_jalan.toLowerCase().includes(search.toLowerCase())) ||
      (r.pemilik_sah && r.pemilik_sah.toLowerCase().includes(search.toLowerCase()))
    )
    .filter((r) => {
      if (filterJenisPemilik === "all") return true;
      return r.jenis_pemilik === filterJenisPemilik;
    })
    .filter((r) => {
      if (filterStatusPenghuni === "all") return true;
      return r.status_penghuni === filterStatusPenghuni;
    })
    .filter((r) => {
      if (filterKosong === "all") return true;
      if (filterKosong === "kosong") return r.sedang_kosong;
      return !r.sedang_kosong;
    });

  // PAGINATION
  const totalPages = Math.ceil(filtered.length / perPage);
  const paginatedData = filtered.slice((page - 1) * perPage, page * perPage);

  // EXPORT EXCEL
  const exportExcel = () => {
    const worksheet = XLSX.utils.json_to_sheet(filtered);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Rumah");
    XLSX.writeFile(workbook, "rumah.xlsx");
  };

  // BULK DELETE
  const doBulkDelete = async () => {
    for (const id of selectedRows) {
      await fetch(`${API_BASE_URL}/api/rumah/${id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
    }
    toast.success(`${selectedRows.length} rumah berhasil dihapus`);
    loadRumah();
    setSelectedRows([]);
    setOpenBulkDelete(false);
  };

  return (
    <div className="p-6 space-y-4">
      {/* HEADER */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold dark:text-gray-100">Daftar Rumah</h1>
          <p className="text-sm text-gray-600 dark:text-gray-400">Kelola data rumah/properti di kompleks</p>
        </div>
        {canCreate('rumah') && (
          <Button
            onClick={() => {
              setSelectedRumah(null);
              setOpenForm(true);
            }}
            className="bg-primary hover:bg-primary/90 text-white"
          >
            + Tambah Rumah
          </Button>
        )}
      </div>

      {/* SEARCH & FILTER */}
      <div className="flex gap-3">
        <Input
          placeholder="Cari blok, jalan, atau pemilik..."
          value={search}
          onChange={(e) => {
            setSearch(e.target.value);
            setPage(1);
          }}
          className="flex-1 dark:bg-gray-800 dark:text-gray-100 dark:border-gray-700"
        />
        <Button
          variant="outline"
          onClick={() => setShowFilter(!showFilter)}
          className="dark:border-gray-700 dark:text-gray-200"
        >
          Filter
        </Button>
      </div>

      {/* FILTER PANEL */}
      {showFilter && (
        <div className="bg-white dark:bg-gray-900 p-6 rounded-lg border dark:border-gray-700 space-y-4">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {/* JENIS PEMILIK */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Jenis Pemilik</label>
              <select
                value={filterJenisPemilik}
                onChange={(e) => {
                  setFilterJenisPemilik(e.target.value);
                  setPage(1);
                }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-gray-50"
              >
                <option value="all">Semua</option>
                <option value="Milik Sendiri">Milik Sendiri</option>
                <option value="Sewa / Kontrak">Sewa / Kontrak</option>
                <option value="Lainnya">Lainnya</option>
              </select>
            </div>

            {/* STATUS PENGHUNI */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Status Penghuni</label>
              <select
                value={filterStatusPenghuni}
                onChange={(e) => {
                  setFilterStatusPenghuni(e.target.value);
                  setPage(1);
                }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-gray-50"
              >
                <option value="all">Semua</option>
                <option value="Pemilik">Pemilik</option>
                <option value="Penghuni Kontrak">Penghuni Kontrak</option>
                <option value="Keluarga Pemilik">Keluarga Pemilik</option>
                <option value="Pemilik Tidak Tinggal">Pemilik Tidak Tinggal</option>
                <option value="Rumah Usaha">Rumah Usaha</option>
                <option value="Kosong">Kosong</option>
              </select>
            </div>

            {/* KOSONG */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Status Kosong</label>
              <select
                value={filterKosong}
                onChange={(e) => {
                  setFilterKosong(e.target.value);
                  setPage(1);
                }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-gray-50"
              >
                <option value="all">Semua</option>
                <option value="kosong">Sedang Kosong</option>
                <option value="ada">Ada Penghuni</option>
              </select>
            </div>

            {/* PER HALAMAN */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Per Halaman</label>
              <select
                value={perPage}
                onChange={(e) => {
                  setPerPage(Number(e.target.value));
                  setPage(1);
                }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-gray-50"
              >
                <option value="5">5</option>
                <option value="10">10</option>
                <option value="25">25</option>
              </select>
            </div>
          </div>
        </div>
      )}

      {/* ACTIONS */}
      {selectedRows.length > 0 && canDelete('rumah') && (
        <div className="flex gap-3 bg-blue-50 dark:bg-blue-900/20 p-4 rounded-lg border border-blue-200 dark:border-blue-800">
          <span className="text-sm dark:text-gray-300">
            {selectedRows.length} item dipilih
          </span>
          <Button
            size="sm"
            variant="destructive"
            onClick={() => setOpenBulkDelete(true)}
          >
            Hapus
          </Button>
          <Button
            size="sm"
            onClick={exportExcel}
            className="bg-green-500 hover:bg-green-600 text-white"
          >
            Export Excel
          </Button>
        </div>
      )}

      {/* TABLE */}
      <div className="bg-white dark:bg-gray-900 rounded-lg border dark:border-gray-700">
        <RumahTable
          data={paginatedData}
          onEdit={(r) => {
            setSelectedRumah(r);
            setOpenForm(true);
          }}
          onDelete={loadRumah}
          selectedRows={selectedRows}
          setSelectedRows={setSelectedRows}
        />
      </div>

      {/* PAGINATION INFO */}
      <div className="flex justify-between items-center text-sm text-gray-600 dark:text-gray-400 px-2">
        <span>
          {filtered.length === 0 ? "Tidak ada data" : `${(page - 1) * perPage + 1}-${Math.min(page * perPage, filtered.length)} dari ${filtered.length}`}
        </span>
        <div className="flex gap-2">
          <Button
            size="sm"
            variant="outline"
            onClick={() => setPage(Math.max(1, page - 1))}
            disabled={page === 1}
            className="dark:border-gray-700 dark:text-gray-200"
          >
            Sebelumnya
          </Button>
          <Button
            size="sm"
            variant="outline"
            onClick={() => setPage(Math.min(totalPages, page + 1))}
            disabled={page === totalPages}
            className="dark:border-gray-700 dark:text-gray-200"
          >
            Selanjutnya
          </Button>
        </div>
      </div>

      {/* FORM MODAL */}
      <RumahFormModal
        open={openForm}
        onOpenChange={setOpenForm}
        rumah={selectedRumah}
        onSaved={() => {
          loadRumah();
          setSelectedRumah(null);
        }}
      />

      {/* BULK DELETE DIALOG */}
      <AlertDialog open={openBulkDelete} onOpenChange={setOpenBulkDelete}>
        <AlertDialogContent className="dark:bg-gray-900 dark:text-gray-100">
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus {selectedRows.length} Rumah?</AlertDialogTitle>
          </AlertDialogHeader>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Tindakan ini tidak dapat dibatalkan.
          </p>
          <AlertDialogFooter>
            <AlertDialogCancel className="dark:bg-gray-800 dark:text-gray-200">
              Batal
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={doBulkDelete}
              className="bg-red-600 hover:bg-red-700"
            >
              Hapus Semua
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
