import { useEffect, useState } from "react";

import { API_BASE_URL } from "@/config/api";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import AksesBotTable from "./AksesBotTable";
import AksesBotForm from "./AksesBotForm";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "@/components/ui/sonner";
import { useRolePermissions } from "@/hooks/useRolePermissions";

export default function AksesBotPage() {
  const [items, setItems] = useState([]);
  const [search, setSearch] = useState("");
  const { token, logout, user } = useAuth();
  const { canCreate, canUpdate, canDelete } = useRolePermissions(user?.role, token);

  const [openForm, setOpenForm] = useState(false);
  const [selectedItem, setSelectedItem] = useState(null);

  const loadItems = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/akses-bot`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (res.status === 401) {
        logout();
        return;
      }

      const data = await res.json();
      setItems(Array.isArray(data) ? data : []);
    } catch (err) {
      console.error("Gagal load akses bot", err);
      toast.error("Gagal memuat data akses bot");
    }
  };

  useEffect(() => {
    loadItems();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const filtered = items.filter(
    (i) =>
      i.nama.toLowerCase().includes(search.toLowerCase()) ||
      i.whatsapp.includes(search)
  );

  return (
    <div className="p-6 space-y-4">
      {/* HEADER */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold dark:text-gray-100">Akses Bot KBBS</h1>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Kelola warga/karyawan yang boleh mengakses Asisten KBBS via WhatsApp
          </p>
        </div>
        {canCreate("akses-bot") && (
          <Button
            onClick={() => {
              setSelectedItem(null);
              setOpenForm(true);
            }}
            className="bg-primary hover:bg-primary/90 text-white"
          >
            + Tambah Akses
          </Button>
        )}
      </div>

      {/* SEARCH */}
      <Input
        placeholder="Cari nama atau nomor WhatsApp..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        className="dark:bg-gray-800 dark:text-gray-100 dark:border-gray-700"
      />

      {/* TABLE */}
      <div className="bg-white dark:bg-gray-900 rounded-lg border dark:border-gray-700">
        <AksesBotTable
          data={filtered}
          onEdit={(item) => {
            setSelectedItem(item);
            setOpenForm(true);
          }}
          onDelete={loadItems}
          canEdit={canUpdate("akses-bot")}
          canDelete={canDelete("akses-bot")}
        />
      </div>

      {/* FORM DIALOG */}
      <AksesBotForm
        open={openForm}
        onOpenChange={setOpenForm}
        item={selectedItem}
        onSaved={() => {
          loadItems();
          setSelectedItem(null);
        }}
      />
    </div>
  );
}
