import React, { useState, useEffect } from 'react';
import { API_BASE_URL } from '../config/api';
import { useNavigate, useSearchParams, useLocation } from 'react-router-dom';
import { Button } from '../components/ui/button';
import { Input } from '../components/ui/input';
import { Label } from '../components/ui/label';
import { Smartphone, Lock, AlertCircle, Eye, EyeOff, Sparkles, ArrowRight, Headset } from 'lucide-react';
import { toast } from '../hooks/use-toast';
import { useAuth } from "../contexts/AuthContext";
import { useTheme } from "../contexts/ThemeContext";
import BrandPanel from '../components/BrandPanel';

const LoginPage = () => {
  const [searchParams] = useSearchParams();
  const location = useLocation();
  
  // Check if we're on forgot password page or have token param
  const isResetPasswordPage = location.pathname === '/lupa-password';
  const tokenFromUrl = searchParams.get('token');
  
  const [mode, setMode] = useState(isResetPasswordPage || tokenFromUrl ? 'forgot' : 'login');
  const [phone, setPhone] = useState(() => localStorage.getItem('kbbs_remembered_phone') || '');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [rememberMe, setRememberMe] = useState(() => !!localStorage.getItem('kbbs_remembered_phone'));
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const { setAuthUser } = useAuth();
  const { heroPattern, heroCustomBg } = useTheme();
  const [kontakBantuan, setKontakBantuan] = useState(null);

  // Ambil kontak WhatsApp pengurus untuk tombol "Butuh bantuan?" (publik, tanpa auth)
  useEffect(() => {
    fetch(`${API_BASE_URL}/api/pengurus/public/kontak-bantuan`)
      .then((res) => (res.ok ? res.json() : null))
      .then((data) => setKontakBantuan(data))
      .catch(() => setKontakBantuan(null));
  }, []);

  // Forgot Password states
  const [forgotStep, setForgotStep] = useState(tokenFromUrl ? 'reset' : 'request');
  const [forgotPhone, setForgotPhone] = useState('');
  const [forgotToken, setForgotToken] = useState(tokenFromUrl || '');
  const [forgotPassword, setForgotPassword] = useState('');
  const [countdown, setCountdown] = useState(0);
  const [forgotError, setForgotError] = useState('');

  const navigate = useNavigate();

  // Auto-switch to forgot password mode if token is in URL
  useEffect(() => {
    if (tokenFromUrl) {
      setMode('forgot');
      setForgotStep('reset');
      setForgotToken(tokenFromUrl);
    }
  }, [tokenFromUrl]);

  // Countdown timer for forgot password
  useEffect(() => {
    if (!countdown) return;
    const timer = setInterval(() => {
      setCountdown((prev) => (prev > 0 ? prev - 1 : 0));
    }, 1000);
    return () => clearInterval(timer);
  }, [countdown]);

  // --------------------------------------------------
  // SUBMIT LOGIN
  // --------------------------------------------------
  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      const res = await fetch(`${API_BASE_URL}/api/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          whatsapp: phone,
          password,
        }),
      });

      // Read response text once and parse (clone to allow middleware to also read)
      const responseText = await res.text();
      let data = {};
      try {
        data = JSON.parse(responseText);
      } catch (e) {
        // Response is not JSON
        data = {};
      }

      if (res.status === 401) {
        setError('No WhatsApp atau password salah');
        return;
      }

      if (res.status === 403) {
        setError('Akun tidak aktif');
        return;
      }

      if (!res.ok) {
        setError(data.detail || 'Terjadi kesalahan, silakan coba lagi');
        return;
      }

      // ⏱️ 30 MENIT
      const expireAt = Date.now() + 30 * 60 * 1000;

      const authUser = {
        id: data.user.id,
        fullname: data.user.fullname,
        whatsapp: data.user.whatsapp,
        role: data.user.role,
      };

      setAuthUser(authUser, data.access_token, expireAt);

      if (rememberMe) {
        localStorage.setItem('kbbs_remembered_phone', phone);
      } else {
        localStorage.removeItem('kbbs_remembered_phone');
      }

      toast({
        title: 'Login Berhasil',
        description: 'Selamat datang di Manajemen Pengurus KBBS',
      });

      navigate('/');
    } catch (err) {
      console.error('Login error:', err);
      setError('Tidak dapat terhubung ke server');
    } finally {
      setIsLoading(false);
    }
  };

  // --------------------------------------------------
  // FORGOT PASSWORD - REQUEST TOKEN
  // --------------------------------------------------
  const handleForgotRequest = async (e) => {
    if (e) e.preventDefault();
    setForgotError('');
    if (!forgotPhone) {
      setForgotError('Masukkan nomor WhatsApp.');
      return;
    }
    setIsLoading(true);
    
    try {
      const res = await fetch(`${API_BASE_URL}/api/registration/request-token`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ whatsapp: forgotPhone, is_forgot_password: true }),
      });
      
      // Read as text first, then parse (auth endpoints skip middleware monitoring)
      const responseText = await res.text();
      let data = {};
      try {
        data = JSON.parse(responseText);
      } catch (parseErr) {
        throw new Error('Response format invalid');
      }
      
      if (!res.ok) {
        throw new Error(data.detail || 'Gagal meminta token');
      }
      
      setCountdown(data.expires_in || 600);
      setForgotStep('verify');
      toast({ title: 'Token dikirim', description: 'Periksa WhatsApp Anda untuk kode 6 digit.' });
      if (data.debug_token) {
        console.info('🔐 Token debug:', data.debug_token);
      }
    } catch (err) {
      console.error('Forgot password request error:', err);
      setForgotError(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  // --------------------------------------------------
  // FORGOT PASSWORD - VERIFY & RESET
  // --------------------------------------------------
  const handleForgotVerify = async (e) => {
    if (e) e.preventDefault();
    setForgotError('');
    if (!forgotToken || !forgotPassword) {
      setForgotError('Masukkan token dan password baru.');
      return;
    }
    
    // For reset step (direct link), no phone needed
    // For verify step (6 digit token), phone needed
    if (forgotStep === 'verify' && !forgotPhone) {
      setForgotError('Masukkan nomor WhatsApp.');
      return;
    }
    
    setIsLoading(true);
    
    try {
      const requestBody = {
        token: forgotToken, 
        password: forgotPassword, 
        is_forgot_password: true 
      };
      
      // Only include whatsapp if it's provided (for 6 digit token flow)
      if (forgotPhone && forgotPhone.trim()) {
        requestBody.whatsapp = forgotPhone;
      }
      
      const res = await fetch(`${API_BASE_URL}/api/registration/verify-token`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(requestBody),
      });

      // Read as text first, then parse (auth endpoints skip middleware monitoring)
      const responseText = await res.text();
      let data = {};
      try {
        data = JSON.parse(responseText);
      } catch (parseErr) {
        throw new Error('Response format invalid');
      }

      if (!res.ok) {
        throw new Error(data.detail || 'Verifikasi gagal');
      }

      toast({ 
        title: 'Password Berhasil Direset', 
        description: 'Silakan login dengan password baru Anda.' 
      });
      
      // Reset forgot password state
      setMode('login');
      setForgotStep('request');
      setForgotPhone('');
      setForgotToken('');
      setForgotPassword('');
      setCountdown(0);
    } catch (err) {
      console.error('Forgot password verify error:', err);
      const errorMessage = err?.message || err?.detail || 'Terjadi kesalahan saat reset password';
      setForgotError(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const inputClass =
    "pl-12 h-11 sm:h-14 bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 rounded-xl text-[15px] " +
    "focus:ring-4 focus:ring-primary/10 focus:border-primary transition-all duration-200";
  const buttonClass =
    "w-full h-11 sm:h-14 bg-primary hover:bg-primary/90 text-primary-foreground font-semibold text-base rounded-xl " +
    "shadow-lg shadow-primary/25 transition-all duration-200 hover:-translate-y-0.5 hover:shadow-xl hover:shadow-primary/30 " +
    "active:translate-y-0 active:shadow-md flex items-center justify-center gap-2 disabled:hover:translate-y-0";

  return (
    <div className="h-dvh md:h-auto md:min-h-screen w-full flex flex-col md:flex-row overflow-hidden md:overflow-x-hidden bg-white dark:bg-gray-900">
      {/* Brand Panel - top on mobile, left on tablet/desktop - full-bleed, tanpa margin/kartu */}
      <div className="md:hidden flex-shrink-0 animate-fade-slide-up">
        <BrandPanel heroPattern={heroPattern} heroCustomBg={heroCustomBg} variant="top" />
      </div>
      <div className="hidden md:block md:w-1/2 animate-fade-slide-left">
        <BrandPanel heroPattern={heroPattern} heroCustomBg={heroCustomBg} variant="side" />
      </div>

      {/* Form Panel */}
      <div className="flex-1 min-h-0 flex items-center justify-center px-5 py-3 sm:px-10 sm:py-10 lg:px-16 bg-white dark:bg-gray-900 overflow-y-auto">
        <div className="w-full max-w-[440px] animate-fade-slide-right">
          <div>
              {mode === 'login' && (
                <p className="flex items-center gap-1.5 text-xs sm:text-sm font-semibold text-primary mb-1 sm:mb-2">
                  <Sparkles className="h-3.5 w-3.5 sm:h-4 sm:w-4 text-accent" />
                  Selamat Datang Kembali
                </p>
              )}
              <h2 className="text-xl sm:text-[26px] lg:text-[28px] font-bold text-[#12332F] dark:text-white tracking-tight leading-[1.15]">
                {mode === 'login' ? 'Masuk Akun' : 'Lupa Password'}
              </h2>
              <p className="mt-1 sm:mt-2 text-xs sm:text-sm text-[#71807D] dark:text-gray-400">
                {mode === 'login' ? 'Masuk dengan No WhatsApp terdaftar' : 'Reset password Anda'}
              </p>
            </div>

            <div className="mt-3 sm:mt-8">
              {/* LOGIN FORM */}
              {mode === 'login' && (
                <form onSubmit={handleSubmit} className="space-y-2.5 sm:space-y-5">
                  <div className="space-y-1 sm:space-y-2">
                    <Label htmlFor="phone" className="text-[#12332F] dark:text-gray-300 text-sm font-medium">No WhatsApp</Label>
                    <div className="relative">
                      <Smartphone className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                      <Input
                        id="phone"
                        type="tel"
                        placeholder="08xxxxxxxxxx"
                        value={phone}
                        onChange={(e) => setPhone(e.target.value)}
                        className={inputClass}
                        disabled={isLoading}
                        autoComplete="tel"
                      />
                    </div>
                  </div>

                  <div className="space-y-1 sm:space-y-2">
                    <Label htmlFor="password" className="text-[#12332F] dark:text-gray-300 text-sm font-medium">Password</Label>
                    <div className="relative">
                      <Lock className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                      <Input
                        id="password"
                        type={showPassword ? 'text' : 'password'}
                        placeholder="Masukkan password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        className={`${inputClass} pr-12`}
                        disabled={isLoading}
                        autoComplete="current-password"
                      />
                      <button
                        type="button"
                        onClick={() => setShowPassword((v) => !v)}
                        className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 hover:text-primary transition-colors"
                        tabIndex={-1}
                        aria-label={showPassword ? 'Sembunyikan password' : 'Tampilkan password'}
                      >
                        {showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
                      </button>
                    </div>
                  </div>

                  <div className="flex items-center justify-between pt-0.5">
                    <label className="flex items-center gap-2 text-sm text-[#71807D] dark:text-gray-400 cursor-pointer select-none">
                      <input
                        type="checkbox"
                        checked={rememberMe}
                        onChange={(e) => setRememberMe(e.target.checked)}
                        className="h-4 w-4 rounded border-gray-300 dark:border-gray-600 accent-[hsl(var(--primary))] cursor-pointer"
                      />
                      Ingat saya
                    </label>
                    <button
                      type="button"
                      className="text-sm font-semibold text-primary hover:underline underline-offset-2"
                      onClick={() => {
                        setMode('forgot');
                        setError('');
                      }}
                      disabled={isLoading}
                    >
                      Lupa Password?
                    </button>
                  </div>

                  {error && (
                    <div className="flex items-center gap-2 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl text-red-600 dark:text-red-400">
                      <AlertCircle className="h-4 w-4 flex-shrink-0" />
                      <p className="text-sm">{error}</p>
                    </div>
                  )}

                  <Button type="submit" className={buttonClass} disabled={isLoading}>
                    {isLoading ? (
                      'Memproses...'
                    ) : (
                      <>
                        Login <ArrowRight className="h-4 w-4" />
                      </>
                    )}
                  </Button>

                  <div className="flex items-center gap-3 pt-1">
                    <span className="h-px flex-1 bg-gray-200 dark:bg-gray-700" />
                    <span className="text-xs text-gray-400">atau</span>
                    <span className="h-px flex-1 bg-gray-200 dark:bg-gray-700" />
                  </div>

                  <div className="text-center">
                    <span className="text-sm text-[#71807D] dark:text-gray-400">Belum punya akun? </span>
                    <Button
                      type="button"
                      variant="link"
                      className="text-primary font-semibold p-0 h-auto"
                      onClick={() => navigate('/register')}
                      disabled={isLoading}
                    >
                      Daftar
                    </Button>
                  </div>
                </form>
              )}

              {/* FORGOT PASSWORD FORM */}
              {mode === 'forgot' && (
                <form onSubmit={forgotStep === 'request' ? handleForgotRequest : handleForgotVerify} className="space-y-2.5 sm:space-y-5">
                  {forgotStep === 'request' && (
                    <>
                      <div className="space-y-1 sm:space-y-2">
                        <Label htmlFor="forgot-phone" className="text-[#12332F] dark:text-gray-300 text-sm font-medium">No WhatsApp</Label>
                        <div className="relative">
                          <Smartphone className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                          <Input
                            id="forgot-phone"
                            type="tel"
                            placeholder="08xxxxxxxxxx"
                            value={forgotPhone}
                            onChange={(e) => setForgotPhone(e.target.value)}
                            className={inputClass}
                            disabled={isLoading}
                            autoComplete="tel"
                          />
                        </div>
                      </div>

                      {forgotError && (
                        <div className="flex items-center gap-2 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl text-red-600 dark:text-red-400">
                          <AlertCircle className="h-4 w-4 flex-shrink-0" />
                          <p className="text-sm">{forgotError}</p>
                        </div>
                      )}

                      <Button type="submit" className={buttonClass} disabled={isLoading}>
                        {isLoading ? 'Memproses...' : 'Minta Token'}
                      </Button>
                    </>
                  )}

                  {forgotStep === 'verify' && (
                    <>
                      <div className="space-y-1 sm:space-y-2">
                        <Label htmlFor="forgot-token" className="text-[#12332F] dark:text-gray-300 text-sm font-medium">Kode Token (6 digit)</Label>
                        <div className="relative">
                          <Lock className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                          <Input
                            id="forgot-token"
                            type="text"
                            placeholder="000000"
                            value={forgotToken}
                            onChange={(e) => setForgotToken(e.target.value.slice(0, 6))}
                            maxLength="6"
                            className={inputClass}
                            disabled={isLoading}
                          />
                        </div>
                        {countdown > 0 && (
                          <p className="text-xs text-[#71807D] dark:text-gray-400">
                            Token berlaku dalam: {Math.floor(countdown / 60)}:{String(countdown % 60).padStart(2, '0')}
                          </p>
                        )}
                      </div>

                      <div className="space-y-1 sm:space-y-2">
                        <Label htmlFor="forgot-password" className="text-[#12332F] dark:text-gray-300 text-sm font-medium">Password Baru</Label>
                        <div className="relative">
                          <Lock className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                          <Input
                            id="forgot-password"
                            type="password"
                            placeholder="Masukkan password baru"
                            value={forgotPassword}
                            onChange={(e) => setForgotPassword(e.target.value)}
                            className={inputClass}
                            disabled={isLoading}
                          />
                        </div>
                      </div>

                      {forgotError && (
                        <div className="flex items-center gap-2 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl text-red-600 dark:text-red-400">
                          <AlertCircle className="h-4 w-4 flex-shrink-0" />
                          <p className="text-sm">{forgotError}</p>
                        </div>
                      )}

                      <Button type="submit" className={buttonClass} disabled={isLoading}>
                        {isLoading ? 'Memproses...' : 'Reset Password'}
                      </Button>
                    </>
                  )}

                  {/* RESET PASSWORD STEP - Direct from link */}
                  {forgotStep === 'reset' && (
                    <>
                      <div className="mb-4 p-4 bg-primary/5 border border-primary/20 rounded-xl">
                        <p className="text-sm text-primary">
                          Token sudah terverifikasi dari link WhatsApp. Masukkan password baru Anda.
                        </p>
                      </div>

                      <div className="space-y-1 sm:space-y-2">
                        <Label htmlFor="reset-password" className="text-[#12332F] dark:text-gray-300 text-sm font-medium">Password Baru</Label>
                        <div className="relative">
                          <Lock className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                          <Input
                            id="reset-password"
                            type="password"
                            placeholder="Masukkan password baru"
                            value={forgotPassword}
                            onChange={(e) => setForgotPassword(e.target.value)}
                            className={inputClass}
                            disabled={isLoading}
                            autoFocus
                          />
                        </div>
                      </div>

                      {forgotError && (
                        <div className="flex items-center gap-2 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl text-red-600 dark:text-red-400">
                          <AlertCircle className="h-4 w-4 flex-shrink-0" />
                          <p className="text-sm">{forgotError}</p>
                        </div>
                      )}

                      <Button type="submit" className={buttonClass} disabled={isLoading}>
                        {isLoading ? 'Memproses...' : 'Reset Password'}
                      </Button>
                    </>
                  )}

                  <div className="text-center pt-2">
                    <Button
                      type="button"
                      variant="ghost"
                      className="text-primary font-semibold hover:bg-primary/10 text-sm"
                      onClick={() => {
                        setMode('login');
                        setForgotStep('request');
                        setForgotPhone('');
                        setForgotToken('');
                        setForgotPassword('');
                        setForgotError('');
                      }}
                      disabled={isLoading}
                    >
                      Kembali ke Login
                    </Button>
                  </div>
                </form>
              )}

              {/* Footer */}
              {kontakBantuan && (
                <div className="pt-2.5 sm:pt-6">
                  <a
                    href={`https://wa.me/${kontakBantuan.no_whatsapp}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center gap-3 p-2.5 sm:p-4 rounded-[14px] border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/60 hover:bg-primary/5 hover:border-primary/30 transition-colors group"
                  >
                    <span className="w-8 h-8 sm:w-9 sm:h-9 rounded-full bg-primary/10 flex items-center justify-center flex-shrink-0">
                      <Headset className="h-4 w-4 text-primary" />
                    </span>
                    <span className="flex-1">
                      <span className="block text-xs text-[#71807D] dark:text-gray-400">Butuh bantuan?</span>
                      <span className="block text-sm font-semibold text-[#12332F] dark:text-white">Hubungi Pengurus KBBS</span>
                    </span>
                    <ArrowRight className="h-4 w-4 text-gray-400 group-hover:text-primary group-hover:translate-x-0.5 transition-all" />
                  </a>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
  );
};

export default LoginPage;
