import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from './ui/select';

const BarChart = ({
  title,
  data,
  dropdownOptions,
  defaultValue,
  selectedMonths,
  onMonthsChange,
  frameless = false,
  className = ''
}) => {
  const handleMonthChange = (value) => {
    const numValue = Number(value);
    if (onMonthsChange) {
      onMonthsChange(numValue);
    }
  };

  // Debug: log incoming data
  console.log('BarChart data received:', data);

  // SVG dimensions
  const width = 600;
  const height = 280;
  const padding = { top: 20, right: 20, bottom: 40, left: 50 };
  const chartWidth = width - padding.left - padding.right;
  const chartHeight = height - padding.top - padding.bottom;
  
  // Get all values for scaling
  const allValues = data.flatMap(item => [item.pemasukan, item.pengeluaran]);
  const maxValue = Math.max(...allValues, 1);
  
  // Calculate bar width and spacing
  const barGroupWidth = chartWidth / data.length;
  const barWidth = barGroupWidth * 0.35; // 35% of group width per bar
  const spacing = barGroupWidth * 0.1;
  
  // Format currency
  const formatCurrency = (value) => {
    return new Intl.NumberFormat('id-ID', {
      style: 'currency',
      currency: 'IDR',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0
    }).format(value);
  };
  
  // Calculate totals
  const totalPemasukan = data.length > 0 ? data[data.length - 1].pemasukan : 0;
  const totalPengeluaran = data.reduce((sum, item) => sum + item.pengeluaran, 0);

  const chartContent = (
    <div className="space-y-4">
      <div className="grid grid-cols-2 gap-4">
        <div className="flex items-center space-x-2">
          <div className="w-4 h-4 bg-green-500 rounded"></div>
          <div>
            <p className="text-xs text-gray-600 dark:text-gray-400">Total Pemasukan</p>
            <p className="text-sm font-semibold text-gray-900 dark:text-white">
              {formatCurrency(totalPemasukan)}
            </p>
          </div>
        </div>
        <div className="flex items-center space-x-2">
          <div className="w-4 h-4 bg-red-500 rounded"></div>
          <div>
            <p className="text-xs text-gray-600 dark:text-gray-400">Total Pengeluaran</p>
            <p className="text-sm font-semibold text-gray-900 dark:text-white">
              {formatCurrency(totalPengeluaran)}
            </p>
          </div>
        </div>
      </div>

      <svg width="100%" height={height} viewBox={`0 0 ${width} ${height}`} className="overflow-visible">
        <line
          x1={padding.left}
          y1={padding.top}
          x2={padding.left}
          y2={height - padding.bottom}
          stroke="#e5e7eb"
          strokeWidth="1"
          className="dark:stroke-gray-700"
        />
        <line
          x1={padding.left}
          y1={height - padding.bottom}
          x2={width - padding.right}
          y2={height - padding.bottom}
          stroke="#e5e7eb"
          strokeWidth="1"
          className="dark:stroke-gray-700"
        />
        {[0, 0.25, 0.5, 0.75, 1].map((ratio, index) => {
          const yValue = maxValue * ratio;
          const y = height - padding.bottom - ratio * chartHeight;
          return (
            <g key={index}>
              <line
                x1={padding.left - 5}
                y1={y}
                x2={padding.left}
                y2={y}
                stroke="#d1d5db"
                strokeWidth="1"
                className="dark:stroke-gray-700"
              />
              <text
                x={padding.left - 10}
                y={y + 4}
                textAnchor="end"
                fontSize="11"
                fill="#6b7280"
                className="dark:fill-gray-500"
              >
                {formatCurrency(yValue)}
              </text>
            </g>
          );
        })}
        {data.map((item, index) => {
          const groupX = padding.left + (index + 0.5) * barGroupWidth;
          const pemasukanHeight = (item.pemasukan / maxValue) * chartHeight;
          const pemasukanY = height - padding.bottom - pemasukanHeight;
          const pengeluaranHeight = (item.pengeluaran / maxValue) * chartHeight;
          const pengeluaranY = height - padding.bottom - pengeluaranHeight;

          return (
            <g key={index}>
              <rect
                x={groupX - barWidth - spacing}
                y={pemasukanY}
                width={barWidth}
                height={pemasukanHeight}
                fill="#10b981"
                className="hover:opacity-80 transition-opacity cursor-pointer"
                rx="3"
              >
                <title>Pemasukan: {formatCurrency(item.pemasukan)}</title>
              </rect>
              <rect
                x={groupX + spacing}
                y={pengeluaranY}
                width={barWidth}
                height={pengeluaranHeight}
                fill="#ef4444"
                className="hover:opacity-80 transition-opacity cursor-pointer"
                rx="3"
              >
                <title>Pengeluaran: {formatCurrency(item.pengeluaran)}</title>
              </rect>
              <text
                x={groupX}
                y={height - padding.bottom + 20}
                textAnchor="middle"
                fontSize="12"
                fill="#6b7280"
                className="dark:fill-gray-500"
              >
                {item.month}
              </text>
            </g>
          );
        })}
      </svg>
    </div>
  );

  if (frameless) {
    return <div className={className}>{chartContent}</div>;
  }

  return (
    <Card className={`hover:shadow-lg transition-shadow duration-200 ${className}`}>
      <CardHeader>
        <div className="flex items-center justify-between">
          <CardTitle className="text-sm font-medium text-gray-600 dark:text-gray-400">
            {title}
          </CardTitle>
          {dropdownOptions && (
            <Select value={selectedMonths.toString()} onValueChange={(val) => handleMonthChange(val)}>
              <SelectTrigger className="w-28 h-8 text-xs">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {dropdownOptions.map((option) => (
                  <SelectItem key={option.value} value={option.value.toString()}>
                    {option.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          )}
        </div>
      </CardHeader>
      <CardContent>
        {chartContent}
      </CardContent>
    </Card>
  );
};

export default BarChart;
