import { useEffect, useState } from "react";

import { API_BASE_URL } from '@/config/api';
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogCancel,
  AlertDialogAction,
  AlertDialogDescription,
} from "@/components/ui/alert-dialog";
import { Label } from "@/components/ui/label";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "@/components/ui/sonner";
import { useRolePermissions } from "@/hooks/useRolePermissions";
import { Pencil, Trash2, Filter, X } from "lucide-react";

export default function DaftarKasbonPage() {
  const [kasbon, setKasbon] = useState([]);
  const [pegawai, setPegawai] = useState([]);
  const [search, setSearch] = useState("");
  const { token, user, logout } = useAuth();
  const { canCreate, canEdit, canDelete } = useRolePermissions(user?.role, token);

  // FORM DIALOG
  const [openForm, setOpenForm] = useState(false);
  const [formData, setFormData] = useState({
    id: null,
    pegawai_id: "",
    nominal: "",
    keterangan: "",
  });

  // DELETE DIALOG
  const [openDelete, setOpenDelete] = useState(false);
  const [deleteId, setDeleteId] = useState(null);

  // FILTER
  const [filterStatus, setFilterStatus] = useState("all");
  const [showFilter, setShowFilter] = useState(false);

  // PAGINATION
  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(25);

  // LOAD DATA
  const loadKasbon = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/kasbon`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.status === 401) {
        logout();
        return;
      }

      const data = await res.json();
      setKasbon(data);
    } catch (err) {
      console.error("Gagal load kasbon", err);
      toast.error("Gagal memuat data kasbon");
    }
  };

  const loadPegawai = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/karyawan`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.ok) {
        const data = await res.json();
        // Filter hanya karyawan yang aktif
        const activePegawai = data.filter((k) => k.status === "active");
        setPegawai(activePegawai);
      }
    } catch (err) {
      console.error("Gagal load pegawai", err);
      toast.error("Gagal memuat data pegawai");
    }
  };

  useEffect(() => {
    loadKasbon();
    loadPegawai();
  }, []);

  // FILTER LOGIC
  const filtered = kasbon
    .filter((k) => {
      const pegawaiName = pegawai.find((p) => p.id === k.pegawai_id)?.nama_lengkap || "";
      return pegawaiName.toLowerCase().includes(search.toLowerCase());
    })
    .filter((k) => {
      if (filterStatus === "all") return true;
      return k.status === filterStatus;
    });

  // PAGINATION
  const totalPages = Math.ceil(filtered.length / perPage);
  const paginatedData = filtered.slice((page - 1) * perPage, page * perPage);

  // HANDLE SAVE
  const handleSave = async () => {
    if (!formData.pegawai_id || !formData.nominal) {
      toast.error("Pegawai dan Nominal harus diisi");
      return;
    }

    try {
      const url = formData.id
        ? `${API_BASE_URL}/api/kasbon/${formData.id}`
        : `${API_BASE_URL}/api/kasbon`;

      const method = formData.id ? "PUT" : "POST";

      const res = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          pegawai_id: formData.pegawai_id,
          nominal: parseFloat(formData.nominal),
          keterangan: formData.keterangan,
        }),
      });

      if (res.ok) {
        toast.success(`Kasbon berhasil ${formData.id ? "diupdate" : "ditambahkan"}`);
        loadKasbon();
        setOpenForm(false);
        resetForm();
      } else {
        const error = await res.json();
        toast.error(error.detail || "Gagal menyimpan kasbon");
      }
    } catch (err) {
      console.error("Error:", err);
      toast.error("Terjadi kesalahan saat menyimpan");
    }
  };

  // HANDLE DELETE
  const handleDelete = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/kasbon/${deleteId}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.ok) {
        toast.success("Kasbon berhasil dihapus");
        loadKasbon();
      } else {
        const error = await res.json();
        toast.error(error.detail || "Gagal menghapus kasbon");
      }
    } catch (err) {
      console.error("Error:", err);
      toast.error("Terjadi kesalahan saat menghapus");
    } finally {
      setOpenDelete(false);
      setDeleteId(null);
    }
  };

  const resetForm = () => {
    setFormData({
      id: null,
      pegawai_id: "",
      nominal: "",
      keterangan: "",
    });
  };

  const openEditForm = (item) => {
    setFormData({
      id: item.id,
      pegawai_id: item.pegawai_id,
      nominal: item.nominal.toString(),
      keterangan: item.keterangan || "",
    });
    setOpenForm(true);
  };

  const openDeleteDialog = (id) => {
    setDeleteId(id);
    setOpenDelete(true);
  };

  const formatRupiah = (val) => {
    return new Intl.NumberFormat("id-ID", {
      style: "currency",
      currency: "IDR",
      minimumFractionDigits: 0,
    }).format(val);
  };

  const getPegawaiName = (pegawaiId) => {
    return pegawai.find((p) => p.id === pegawaiId)?.nama_lengkap || "-";
  };

  const handleNominalChange = (e) => {
    // Remove all non-digit characters
    const value = e.target.value.replace(/\D/g, '');
    setFormData({ ...formData, nominal: value });
  };

  const displayNominal = () => {
    if (!formData.nominal) return '';
    return new Intl.NumberFormat("id-ID").format(formData.nominal);
  };

  return (
    <div className="p-6 space-y-6">
      {/* HEADER */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold dark:text-gray-100">Daftar Kasbon</h1>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Kelola kasbon / pinjaman pegawai
          </p>
        </div>
        {canCreate("kasbon") && (
          <Button
            onClick={() => {
              resetForm();
              setOpenForm(true);
            }}
            className="bg-primary hover:bg-primary/90 text-white"
          >
            + Tambah Kasbon
          </Button>
        )}
      </div>

      {/* SEARCH & FILTER */}
      <div className="bg-white dark:bg-gray-900 p-4 rounded-lg border dark:border-gray-700 space-y-3">
        <div className="flex gap-3 items-center">
          <Input
            placeholder="Cari nama pegawai..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="max-w-sm"
          />
          <Button
            variant="outline"
            onClick={() => setShowFilter(!showFilter)}
            className="gap-2"
          >
            <Filter className="h-4 w-4" />
            Filter
          </Button>
        </div>

        {showFilter && (
          <div className="flex gap-3 items-center pt-2 border-t dark:border-gray-700">
            <Label className="text-sm">Status:</Label>
            <Select value={filterStatus} onValueChange={setFilterStatus}>
              <SelectTrigger className="w-64">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Semua Status</SelectItem>
                <SelectItem value="Belum Lunas">Belum Lunas</SelectItem>
                <SelectItem value="Lunas">Lunas</SelectItem>
              </SelectContent>
            </Select>
            {filterStatus !== "all" && (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setFilterStatus("all")}
                className="gap-1"
              >
                <X className="h-4 w-4" />
                Reset
              </Button>
            )}
          </div>
        )}
      </div>

      {/* TABLE */}
      <div className="bg-white dark:bg-gray-900 rounded-lg border dark:border-gray-700">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Nama Pegawai</TableHead>
              <TableHead className="text-right">Nominal</TableHead>
              <TableHead className="text-right">Sisa</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Tanggal</TableHead>
              <TableHead className="text-right">Aksi</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {paginatedData.length === 0 ? (
              <TableRow>
                <TableCell colSpan={6} className="text-center text-gray-500">
                  Tidak ada data kasbon
                </TableCell>
              </TableRow>
            ) : (
              paginatedData.map((item) => (
                <TableRow key={item.id}>
                  <TableCell>
                    <p className="font-medium">{getPegawaiName(item.pegawai_id)}</p>
                    {item.keterangan && (
                      <p className="text-xs text-gray-500">{item.keterangan}</p>
                    )}
                  </TableCell>
                  <TableCell className="text-right font-medium">
                    {formatRupiah(item.nominal)}
                  </TableCell>
                  <TableCell className="text-right font-medium">
                    {formatRupiah(item.sisa)}
                  </TableCell>
                  <TableCell>
                    <span
                      className={`px-2 py-1 rounded text-xs font-semibold ${
                        item.status === "Lunas"
                          ? "bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300"
                          : "bg-yellow-100 text-yellow-700 dark:bg-yellow-900 dark:text-yellow-300"
                      }`}
                    >
                      {item.status}
                    </span>
                  </TableCell>
                  <TableCell className="text-sm">
                    {item.tanggal ? new Date(item.tanggal).toLocaleDateString("id-ID") : "-"}
                  </TableCell>
                  <TableCell className="text-right space-x-2">
                    {canEdit("kasbon") && item.status !== "Lunas" && (
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => openEditForm(item)}
                      >
                        <Pencil className="h-4 w-4" />
                      </Button>
                    )}
                    {canDelete("kasbon") && item.status !== "Lunas" && (
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => openDeleteDialog(item.id)}
                      >
                        <Trash2 className="h-4 w-4 text-red-500" />
                      </Button>
                    )}
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>

        {/* PAGINATION */}
        {totalPages > 1 && (
          <div className="p-4 border-t dark:border-gray-700 flex justify-between items-center">
            <p className="text-sm text-gray-600 dark:text-gray-400">
              Halaman {page} dari {totalPages} ({filtered.length} total)
            </p>
            <div className="flex gap-2">
              <Button
                variant="outline"
                size="sm"
                disabled={page === 1}
                onClick={() => setPage(page - 1)}
              >
                Previous
              </Button>
              <Button
                variant="outline"
                size="sm"
                disabled={page === totalPages}
                onClick={() => setPage(page + 1)}
              >
                Next
              </Button>
            </div>
          </div>
        )}
      </div>

      {/* FORM DIALOG */}
      <Dialog open={openForm} onOpenChange={setOpenForm}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>
              {formData.id ? "Edit Kasbon" : "Tambah Kasbon"}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label htmlFor="pegawai">Pegawai</Label>
              <Select
                value={formData.pegawai_id}
                onValueChange={(value) => setFormData({ ...formData, pegawai_id: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Pilih pegawai" />
                </SelectTrigger>
                <SelectContent>
                  {pegawai.length === 0 ? (
                    <div className="p-2 text-sm text-gray-500">Tidak ada pegawai</div>
                  ) : (
                    pegawai.map((p) => (
                      <SelectItem key={p.id} value={p.id}>
                        {p.nama_lengkap} {p.jabatan && `(${p.jabatan})`}
                      </SelectItem>
                    ))
                  )}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label htmlFor="nominal">Nominal (Rp)</Label>
              <Input
                id="nominal"
                type="text"
                value={displayNominal()}
                onChange={handleNominalChange}
                placeholder="500000"
              />
            </div>
            <div>
              <Label htmlFor="keterangan">Keterangan (Opsional)</Label>
              <Input
                id="keterangan"
                value={formData.keterangan}
                onChange={(e) => setFormData({ ...formData, keterangan: e.target.value })}
                placeholder="Keperluan kasbon"
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setOpenForm(false)}>
              Batal
            </Button>
            <Button onClick={handleSave}>Simpan</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* DELETE CONFIRMATION */}
      <AlertDialog open={openDelete} onOpenChange={setOpenDelete}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Kasbon</AlertDialogTitle>
            <AlertDialogDescription>
              Apakah Anda yakin ingin menghapus kasbon ini? Kasbon yang sudah lunas tidak
              bisa dihapus.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Batal</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              className="bg-red-500 hover:bg-red-600"
            >
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
