// "#rrggbb" -> "H S% L%" (format triplet yang dipakai variable CSS di atas)
export function hexToHslTriplet(hex) {
  let r = 0, g = 0, b = 0;
  const clean = hex.replace('#', '');
  if (clean.length === 3) {
    r = parseInt(clean[0] + clean[0], 16);
    g = parseInt(clean[1] + clean[1], 16);
    b = parseInt(clean[2] + clean[2], 16);
  } else if (clean.length === 6) {
    r = parseInt(clean.slice(0, 2), 16);
    g = parseInt(clean.slice(2, 4), 16);
    b = parseInt(clean.slice(4, 6), 16);
  } else {
    return '158 64% 27%';
  }
  r /= 255; g /= 255; b /= 255;
  const max = Math.max(r, g, b), min = Math.min(r, g, b);
  let h = 0, s = 0;
  const l = (max + min) / 2;
  if (max !== min) {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    switch (max) {
      case r: h = (g - b) / d + (g < b ? 6 : 0); break;
      case g: h = (b - r) / d + 2; break;
      default: h = (r - g) / d + 4; break;
    }
    h /= 6;
  }
  return `${Math.round(h * 360)} ${Math.round(s * 100)}% ${Math.round(l * 100)}%`;
}

// Turunkan warna foreground gelap/terang otomatis dari lightness hex-nya.
export function foregroundForHex(hex) {
  const clean = hex.replace('#', '');
  if (clean.length !== 6) return '0 0% 100%';
  const r = parseInt(clean.slice(0, 2), 16);
  const g = parseInt(clean.slice(2, 4), 16);
  const b = parseInt(clean.slice(4, 6), 16);
  const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return luminance > 0.6 ? '0 0% 10%' : '0 0% 100%';
}

// Turunkan versi lebih gelap dari triplet HSL "H S% L%" (dipakai untuk
// gradient hero panel login), dengan lightness dikurangi tapi tidak sampai
// negatif.
export function darkenTriplet(triplet, deltaL = 10) {
  const [h, s, l] = triplet.split(' ').map((part) => parseInt(part, 10));
  const newL = Math.max(4, l - deltaL);
  return `${h} ${s}% ${newL}%`;
}

export function buildCustomThemeVars(customColors) {
  const primary = hexToHslTriplet(customColors.primary);
  const accent = hexToHslTriplet(customColors.accent);
  // Latar halaman: pakai warna eksplisit dari user kalau diisi, kalau tidak
  // turunkan otomatis dari hue primary (tipis - saturasi rendah, lightness tinggi).
  const [h] = primary.split(' ');
  const background = customColors.background ? hexToHslTriplet(customColors.background) : `${h} 20% 96%`;
  // Sidebar/header (card) sedikit lebih ditinting dari background, biar beda tema
  // kelihatan jelas di sidebar juga, bukan cuma putih polos.
  const card = `${h} 30% 97%`;
  return {
    primary,
    primaryDark: darkenTriplet(primary, 10),
    primaryForeground: foregroundForHex(customColors.primary),
    accent,
    accentForeground: foregroundForHex(customColors.accent),
    ring: primary,
    background,
    card,
  };
}
