import { useState } from "react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { API_BASE_URL } from "@/config/api";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { CheckCircle2, XCircle } from "lucide-react";
import { toast } from "@/components/ui/sonner";
import { useAuth } from "@/contexts/AuthContext";

const ROLE_LABEL = { admin: "Admin", warga: "Warga", karyawan: "Karyawan" };
const ROLE_BADGE_CLASS = {
  admin: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
  warga: "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400",
  karyawan: "bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400",
};

export default function AksesBotTable({ data, onEdit, onDelete, canEdit, canDelete }) {
  const { token } = useAuth();
  const [showDeleteAlert, setShowDeleteAlert] = useState(false);
  const [selectedForDelete, setSelectedForDelete] = useState(null);

  const handleDelete = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/akses-bot/${selectedForDelete}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });

      if (res.ok) {
        toast.success("Akses bot berhasil dihapus!");
        onDelete();
        setShowDeleteAlert(false);
      } else {
        toast.error("Gagal menghapus akses bot");
      }
    } catch (err) {
      toast.error("Tidak dapat terhubung ke server");
      console.error(err);
    }
  };

  return (
    <>
      <div className="border rounded-lg overflow-hidden dark:border-gray-700">
        <Table className="dark:bg-gray-800">
          <TableHeader>
            <TableRow className="dark:border-gray-700">
              <TableHead className="dark:text-gray-400">Nama</TableHead>
              <TableHead className="dark:text-gray-400">No. WhatsApp</TableHead>
              <TableHead className="dark:text-gray-400">Role Akses</TableHead>
              <TableHead className="text-center dark:text-gray-400">Izin Transaksi</TableHead>
              <TableHead className="text-center dark:text-gray-400">Status</TableHead>
              {(canEdit || canDelete) && (
                <TableHead className="text-right dark:text-gray-400">Aksi</TableHead>
              )}
            </TableRow>
          </TableHeader>
          <TableBody>
            {data.length === 0 ? (
              <TableRow>
                <TableCell colSpan={6} className="text-center text-gray-500 py-8">
                  Tidak ada data
                </TableCell>
              </TableRow>
            ) : (
              data.map((item) => (
                <TableRow key={item.id} className="dark:border-gray-700 dark:hover:bg-gray-700">
                  <TableCell className="font-medium dark:text-gray-100">{item.nama}</TableCell>
                  <TableCell className="dark:text-gray-300">{item.whatsapp}</TableCell>
                  <TableCell>
                    <span
                      className={`text-xs font-semibold px-2 py-1 rounded-full ${
                        ROLE_BADGE_CLASS[item.role] || ""
                      }`}
                    >
                      {ROLE_LABEL[item.role] || item.role}
                    </span>
                  </TableCell>
                  <TableCell className="text-center">
                    {item.akses_transaksi ? (
                      <span className="text-xs font-semibold px-2 py-1 rounded-full bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400">
                        Diizinkan
                      </span>
                    ) : (
                      <span className="text-xs font-semibold px-2 py-1 rounded-full bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400">
                        Tidak
                      </span>
                    )}
                  </TableCell>
                  <TableCell className="text-center">
                    {item.aktif ? (
                      <CheckCircle2 className="w-5 h-5 text-green-500 mx-auto" />
                    ) : (
                      <XCircle className="w-5 h-5 text-red-500 mx-auto" />
                    )}
                  </TableCell>
                  {(canEdit || canDelete) && (
                    <TableCell className="text-right space-x-2">
                      {canEdit && (
                        <Button
                          onClick={() => onEdit(item)}
                          className="bg-blue-500 hover:bg-blue-600 text-white"
                          size="sm"
                        >
                          Edit
                        </Button>
                      )}
                      {canDelete && (
                        <Button
                          onClick={() => {
                            setSelectedForDelete(item.id);
                            setShowDeleteAlert(true);
                          }}
                          variant="destructive"
                          size="sm"
                        >
                          Hapus
                        </Button>
                      )}
                    </TableCell>
                  )}
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      {/* DELETE ALERT */}
      <AlertDialog open={showDeleteAlert} onOpenChange={setShowDeleteAlert}>
        <AlertDialogContent className="dark:bg-gray-900">
          <AlertDialogTitle className="dark:text-gray-100">Hapus Akses Bot?</AlertDialogTitle>
          <AlertDialogDescription className="dark:text-gray-400">
            Nomor ini tidak akan bisa lagi mengakses Asisten KBBS via WhatsApp. Tindakan ini tidak dapat dibatalkan.
          </AlertDialogDescription>
          <div className="flex gap-3 justify-end">
            <AlertDialogCancel className="dark:border-gray-700 dark:hover:bg-gray-800">
              Batal
            </AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-red-600 hover:bg-red-700">
              Hapus
            </AlertDialogAction>
          </div>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}
