import React, { useState, useEffect, useCallback, useRef } from 'react';
import {
  Newspaper, Plus, Loader2, ImagePlus, X, Pencil, Trash2, Search, ChevronLeft, ChevronRight,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Card, CardContent } from '@/components/ui/card';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter,
} from '@/components/ui/dialog';
import {
  AlertDialog, AlertDialogContent, AlertDialogHeader, AlertDialogTitle,
  AlertDialogDescription, AlertDialogFooter, AlertDialogCancel, AlertDialogAction,
} from '@/components/ui/alert-dialog';
import { useAuth } from '@/contexts/AuthContext';
import { toast } from '@/components/ui/sonner';
import { API_BASE_URL, API_ENDPOINTS } from '@/config/api';

const imgUrl = (path) => `${API_BASE_URL}${path}`;

const ROLE_LABEL = { admin: 'Admin', karyawan: 'Karyawan', warga: 'Warga', staff: 'Staff' };
const ROLE_DOT = {
  admin: 'bg-amber-600',
  karyawan: 'bg-sky-600',
  staff: 'bg-sky-600',
  warga: 'bg-emerald-600',
};
const ROLE_TEXT = {
  admin: 'text-amber-700',
  karyawan: 'text-sky-700',
  staff: 'text-sky-700',
  warga: 'text-emerald-700',
};

function waktuRelatif(iso) {
  const diffMs = Date.now() - new Date(iso).getTime();
  const menit = Math.floor(diffMs / 60000);
  if (menit < 1) return 'Baru saja';
  if (menit < 60) return `${menit} menit lalu`;
  const jam = Math.floor(menit / 60);
  if (jam < 24) return `${jam} jam lalu`;
  const hari = Math.floor(jam / 24);
  if (hari < 7) return `${hari} hari lalu`;
  return new Date(iso).toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' });
}

function initials(nama) {
  return (nama || '?').trim().split(/\s+/).slice(0, 2).map(w => w[0]).join('').toUpperCase();
}

// ── Lightbox galeri foto ─────────────────────────────────────────────────

function ImageLightbox({ images, index, onClose, onIndexChange }) {
  if (index == null) return null;
  return (
    <Dialog open={index != null} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="sm:max-w-3xl p-2 bg-black border-none">
        <div className="relative flex items-center justify-center min-h-[50vh]">
          {images.length > 1 && (
            <button
              onClick={() => onIndexChange((index - 1 + images.length) % images.length)}
              className="absolute left-2 z-10 bg-white/20 hover:bg-white/40 rounded-full p-2 text-white"
            >
              <ChevronLeft size={20} />
            </button>
          )}
          <img src={imgUrl(images[index])} alt="" className="max-h-[75vh] max-w-full object-contain rounded" />
          {images.length > 1 && (
            <button
              onClick={() => onIndexChange((index + 1) % images.length)}
              className="absolute right-2 z-10 bg-white/20 hover:bg-white/40 rounded-full p-2 text-white"
            >
              <ChevronRight size={20} />
            </button>
          )}
        </div>
        {images.length > 1 && (
          <p className="text-center text-white/70 text-xs pb-1">{index + 1} / {images.length}</p>
        )}
      </DialogContent>
    </Dialog>
  );
}

// ── Grid galeri foto di dalam kartu ───────────────────────────────────────

function ImageGrid({ images, onOpen }) {
  if (!images || images.length === 0) return null;
  const shown = images.slice(0, 4);
  const sisa = images.length - shown.length;
  return (
    <div className={`grid gap-1 rounded-xl overflow-hidden mt-4 border border-stone-200/70 ${shown.length === 1 ? 'grid-cols-1' : 'grid-cols-2'}`}>
      {shown.map((img, i) => (
        <button
          key={i}
          onClick={() => onOpen(i)}
          className="relative bg-gray-100 aspect-video overflow-hidden"
        >
          <img src={imgUrl(img)} alt="" className="w-full h-full object-cover hover:scale-105 transition-transform" />
          {i === 3 && sisa > 0 && (
            <div className="absolute inset-0 bg-black/50 flex items-center justify-center text-white font-semibold">
              +{sisa}
            </div>
          )}
        </button>
      ))}
    </div>
  );
}

// ── Form Buat / Edit Buletin ──────────────────────────────────────────────

function BuletinFormDialog({ open, onClose, editing, onSaved }) {
  const [judul, setJudul] = useState('');
  const [konten, setKonten] = useState('');
  const [newFiles, setNewFiles] = useState([]);       // File[] gambar baru (belum di-upload, khusus create atau nambah di edit)
  const [existingImages, setExistingImages] = useState([]); // untuk mode edit
  const [saving, setSaving] = useState(false);
  const fileInputRef = useRef(null);

  useEffect(() => {
    if (open) {
      setJudul(editing?.judul || '');
      setKonten(editing?.konten || '');
      setExistingImages(editing?.images || []);
      setNewFiles([]);
    }
  }, [open, editing]);

  const totalImageCount = existingImages.length + newFiles.length;

  const handlePickFiles = (e) => {
    const picked = Array.from(e.target.files || []);
    if (totalImageCount + picked.length > 8) {
      toast.error('Maksimal 8 gambar per postingan');
      return;
    }
    setNewFiles(prev => [...prev, ...picked]);
    e.target.value = '';
  };

  const removeNewFile = (i) => setNewFiles(prev => prev.filter((_, idx) => idx !== i));

  const removeExistingImage = async (i) => {
    if (!editing) return;
    try {
      const res = await API_ENDPOINTS.buletinDeleteImage(editing.id, i);
      setExistingImages(res.images);
      toast.success('Gambar dihapus');
    } catch (e) {
      toast.error(e.message || 'Gagal menghapus gambar');
    }
  };

  const handleSubmit = async () => {
    if (!judul.trim()) { toast.error('Judul harus diisi'); return; }
    if (!konten.trim()) { toast.error('Isi berita harus diisi'); return; }
    setSaving(true);
    try {
      if (editing) {
        await API_ENDPOINTS.buletinUpdate(editing.id, { judul, konten });
        if (newFiles.length > 0) {
          await API_ENDPOINTS.buletinAddImages(editing.id, newFiles);
        }
        toast.success('Buletin berhasil diperbarui');
      } else {
        await API_ENDPOINTS.buletinCreate({ judul, konten, files: newFiles });
        toast.success('Buletin berhasil dipublikasikan');
      }
      onSaved();
      onClose();
    } catch (e) {
      toast.error(e.message || 'Gagal menyimpan buletin');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="sm:max-w-lg max-h-[85vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{editing ? 'Edit Buletin' : 'Buat Buletin Baru'}</DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          <div className="space-y-1.5">
            <Label className="text-xs">Judul</Label>
            <Input value={judul} onChange={e => setJudul(e.target.value)} placeholder="mis. Kerja Bakti Akhir Pekan" />
          </div>
          <div className="space-y-1.5">
            <Label className="text-xs">Isi Berita</Label>
            <Textarea value={konten} onChange={e => setKonten(e.target.value)} rows={5} placeholder="Tulis informasi/berita di sini..." />
          </div>

          <div className="space-y-2">
            <Label className="text-xs">Foto (opsional, maks 8)</Label>
            <div className="grid grid-cols-4 gap-2">
              {existingImages.map((img, i) => (
                <div key={`existing-${i}`} className="relative aspect-square rounded-lg overflow-hidden border group">
                  <img src={imgUrl(img)} alt="" className="w-full h-full object-cover" />
                  <button
                    onClick={() => removeExistingImage(i)}
                    className="absolute top-1 right-1 bg-black/60 text-white rounded-full p-0.5 opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <X size={12} />
                  </button>
                </div>
              ))}
              {newFiles.map((f, i) => (
                <div key={`new-${i}`} className="relative aspect-square rounded-lg overflow-hidden border group">
                  <img src={URL.createObjectURL(f)} alt="" className="w-full h-full object-cover" />
                  <button
                    onClick={() => removeNewFile(i)}
                    className="absolute top-1 right-1 bg-black/60 text-white rounded-full p-0.5 opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <X size={12} />
                  </button>
                </div>
              ))}
              {totalImageCount < 8 && (
                <button
                  onClick={() => fileInputRef.current?.click()}
                  className="aspect-square rounded-lg border-2 border-dashed flex items-center justify-center text-gray-400 hover:text-primary hover:border-primary transition-colors"
                >
                  <ImagePlus size={20} />
                </button>
              )}
            </div>
            <input
              ref={fileInputRef}
              type="file"
              accept="image/*"
              multiple
              className="hidden"
              onChange={handlePickFiles}
            />
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={onClose} disabled={saving}>Batal</Button>
          <Button onClick={handleSubmit} disabled={saving} className="gap-1.5">
            {saving ? <Loader2 size={15} className="animate-spin" /> : null}
            {editing ? 'Simpan Perubahan' : 'Publikasikan'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

// ── Satu kartu postingan ───────────────────────────────────────────────

function BuletinCard({ post, currentUser, onEdit, onDeleted }) {
  const [lightboxIndex, setLightboxIndex] = useState(null);
  const [expanded, setExpanded] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [deleting, setDeleting] = useState(false);

  const canManage = currentUser?.role === 'admin' || post.created_by_user_id === currentUser?.id;
  const isLong = post.konten.length > 280;
  const displayText = expanded || !isLong ? post.konten : post.konten.slice(0, 280) + '…';

  const handleDelete = async () => {
    setDeleting(true);
    try {
      await API_ENDPOINTS.buletinDelete(post.id);
      toast.success('Buletin dihapus');
      onDeleted(post.id);
    } catch (e) {
      toast.error(e.message || 'Gagal menghapus buletin');
    } finally {
      setDeleting(false);
      setConfirmDelete(false);
    }
  };

  return (
    <Card className="group border-stone-200/80 rounded-2xl shadow-none hover:shadow-md transition-shadow duration-200">
      <CardContent className="p-5 sm:p-6">
        <div className="flex items-start justify-between gap-2">
          <div className="flex items-center gap-3">
            <Avatar className="h-10 w-10 border border-stone-200">
              <AvatarFallback className="text-xs font-semibold bg-stone-100 text-stone-700">
                {initials(post.created_by_nama)}
              </AvatarFallback>
            </Avatar>
            <div>
              <div className="flex items-center gap-2 flex-wrap leading-tight">
                <span className="font-medium text-sm text-stone-900">{post.created_by_nama}</span>
                <span className={`inline-flex items-center gap-1 text-[11px] font-medium uppercase tracking-wide ${ROLE_TEXT[post.created_by_role] || 'text-stone-500'}`}>
                  <span className={`h-1.5 w-1.5 rounded-full ${ROLE_DOT[post.created_by_role] || 'bg-stone-400'}`} />
                  {ROLE_LABEL[post.created_by_role] || post.created_by_role}
                </span>
              </div>
              <p className="text-xs text-stone-400 mt-0.5">
                {waktuRelatif(post.created_at)}
                {post.updated_at !== post.created_at && ' · disunting'}
              </p>
            </div>
          </div>
          {canManage && (
            <div className="flex gap-1 shrink-0 opacity-0 group-hover:opacity-100 focus-within:opacity-100 transition-opacity">
              <Button size="icon" variant="ghost" className="h-7 w-7" onClick={() => onEdit(post)}>
                <Pencil size={13} />
              </Button>
              <Button size="icon" variant="ghost" className="h-7 w-7 text-red-500 hover:text-red-600" onClick={() => setConfirmDelete(true)}>
                <Trash2 size={13} />
              </Button>
            </div>
          )}
        </div>

        <h3 className="font-serif text-[1.2rem] font-semibold text-stone-900 leading-snug mt-4">{post.judul}</h3>
        <p className="text-[0.925rem] text-stone-600 whitespace-pre-wrap mt-1.5 leading-relaxed">
          {displayText}
          {isLong && (
            <button onClick={() => setExpanded(v => !v)} className="text-amber-700 text-sm font-medium ml-1.5 hover:underline underline-offset-2">
              {expanded ? 'Sembunyikan' : 'Baca selengkapnya'}
            </button>
          )}
        </p>

        <ImageGrid images={post.images} onOpen={setLightboxIndex} />
      </CardContent>

      <ImageLightbox
        images={post.images}
        index={lightboxIndex}
        onClose={() => setLightboxIndex(null)}
        onIndexChange={setLightboxIndex}
      />

      <AlertDialog open={confirmDelete} onOpenChange={setConfirmDelete}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus buletin "{post.judul}"?</AlertDialogTitle>
            <AlertDialogDescription>Postingan ini akan dihapus permanen beserta semua fotonya.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Batal</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} disabled={deleting} className="bg-red-600 hover:bg-red-700">
              {deleting ? <Loader2 size={14} className="animate-spin mr-1.5" /> : null}Ya, Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </Card>
  );
}

// ── Rail: ringkasan papan ────────────────────────────────────────────────

function RailRingkasan({ posts }) {
  const total = posts.length;
  const perRole = posts.reduce((acc, p) => {
    acc[p.created_by_role] = (acc[p.created_by_role] || 0) + 1;
    return acc;
  }, {});
  const rows = [
    { key: 'warga', label: 'Dari Warga' },
    { key: 'karyawan', label: 'Dari Karyawan' },
    { key: 'admin', label: 'Dari Admin' },
  ];
  return (
    <div className="rounded-2xl border border-stone-200/80 bg-white p-5 space-y-4">
      <div>
        <p className="text-[11px] font-medium uppercase tracking-wide text-stone-400">Papan Ini Berisi</p>
        <p className="font-serif text-3xl font-semibold text-stone-900 mt-0.5">{total}</p>
        <p className="text-xs text-stone-500">postingan aktif</p>
      </div>
      <div className="h-px bg-stone-100" />
      <dl className="space-y-2.5">
        {rows.map(r => (
          <div key={r.key} className="flex items-center justify-between text-sm">
            <dt className="flex items-center gap-1.5 text-stone-500">
              <span className={`h-1.5 w-1.5 rounded-full ${ROLE_DOT[r.key]}`} />
              {r.label}
            </dt>
            <dd className="font-medium text-stone-900">{perRole[r.key] || 0}</dd>
          </div>
        ))}
      </dl>
    </div>
  );
}

// ── Page ─────────────────────────────────────────────────────────────────

export default function BuletinPage() {
  const { user } = useAuth();
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [formOpen, setFormOpen] = useState(false);
  const [editing, setEditing] = useState(null);

  const load = useCallback(async (searchTerm) => {
    setLoading(true);
    try {
      const res = await API_ENDPOINTS.buletinList(searchTerm);
      setPosts(res);
    } catch (e) {
      toast.error(e.message || 'Gagal memuat buletin');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  useEffect(() => {
    const t = setTimeout(() => load(search || undefined), 350);
    return () => clearTimeout(t);
    // eslint-disable-next-line
  }, [search]);

  const dateline = new Date().toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });

  return (
    <div className="bg-stone-50/60 min-h-full">
      <div className="max-w-6xl mx-auto p-4 sm:p-8">
        {/* Masthead */}
        <div className="flex items-start justify-between gap-4 flex-wrap">
          <div>
            <p className="text-[11px] font-medium uppercase tracking-[0.2em] text-amber-700">Papan Informasi Warga</p>
            <h1 className="font-serif text-4xl sm:text-[2.75rem] font-semibold text-stone-900 tracking-tight leading-none mt-1">
              Buletin KBBS
            </h1>
          </div>
          <Button onClick={() => { setEditing(null); setFormOpen(true); }} size="lg" className="gap-1.5 shrink-0">
            <Plus size={17} /> Buat Buletin
          </Button>
        </div>
        <div className="h-px bg-stone-900 mt-4" />
        <div className="h-px bg-stone-900 mt-1 mb-3" />
        <p className="text-sm text-stone-500">
          Perumahan Botanika Sriwidari, Kota Sukabumi &middot; {dateline}
        </p>

        {/* Konten: feed + rail */}
        <div className="mt-8 grid lg:grid-cols-[1fr_18rem] gap-8 items-start">
          <div className="space-y-4 min-w-0">
            <div className="relative">
              <Search size={15} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-stone-400" />
              <Input
                value={search}
                onChange={e => setSearch(e.target.value)}
                placeholder="Cari judul, isi, atau nama..."
                className="pl-9 bg-white rounded-xl border-stone-200"
              />
            </div>

            {loading ? (
              <div className="flex justify-center py-20"><Loader2 className="animate-spin text-stone-400" size={26} /></div>
            ) : posts.length === 0 ? (
              <div className="text-center py-20 rounded-2xl border border-dashed border-stone-300">
                <Newspaper className="mx-auto text-stone-300" size={30} />
                <p className="text-stone-500 mt-3 text-sm">
                  {search ? `Tidak ada buletin yang cocok dengan "${search}".` : 'Papan ini masih kosong.'}
                </p>
                {!search && (
                  <Button variant="outline" size="sm" className="mt-3 gap-1.5" onClick={() => { setEditing(null); setFormOpen(true); }}>
                    <Plus size={14} /> Tulis buletin pertama
                  </Button>
                )}
              </div>
            ) : (
              <div className="space-y-4">
                {posts.map(post => (
                  <BuletinCard
                    key={post.id}
                    post={post}
                    currentUser={user}
                    onEdit={(p) => { setEditing(p); setFormOpen(true); }}
                    onDeleted={(id) => setPosts(prev => prev.filter(p => p.id !== id))}
                  />
                ))}
              </div>
            )}
          </div>

          <div className="hidden lg:block sticky top-6">
            <RailRingkasan posts={posts} />
          </div>
        </div>
      </div>

      <BuletinFormDialog
        open={formOpen}
        editing={editing}
        onClose={() => setFormOpen(false)}
        onSaved={() => load(search || undefined)}
      />
    </div>
  );
}
