import loginIllustration from '../assets/images/logo-login.png';
import LoginHeroBackground from './LoginHeroBackground';
import { API_BASE_URL } from '../config/api';

// ─── FOTO LATAR ──────────────────────────────────────────────────────────
// Foto asli lingkungan Perumahan Botanika. Untuk ganti foto ini, tinggal
// timpa file src/assets/images/background.jpg dengan foto baru (rasio
// landscape, resolusi minimal 1200px lebar) - tidak perlu ubah kode apa pun.
import heroBgImage from '../assets/images/background.jpg';
const HERO_BG_IMAGE = heroBgImage;

/**
 * Panel branding halaman login - dipakai baik sebagai panel KIRI (variant="side",
 * desktop/tablet, curve vertikal di sisi kanan) maupun panel ATAS (variant="top",
 * mobile, curve horizontal di sisi bawah). Warna & pattern latar mengikuti tema
 * aktif (lihat ThemeContext + colorThemes.js) - komponen ini sendiri tidak
 * hardcode warna brand, cuma neutral (putih/emas transparan) di atasnya.
 */
const BrandPanel = ({ heroPattern, heroCustomBg, variant = 'side' }) => {
  const isTop = variant === 'top';
  // Latar diprioritaskan: foto custom yang diupload admin (kalau gaya "Custom"
  // dipilih & sudah ada file) -> foto default bundel -> pattern SVG/gradient.
  const bgImageSrc = heroPattern === 'custom' && heroCustomBg
    ? `${API_BASE_URL}${heroCustomBg}`
    : HERO_BG_IMAGE;

  return (
    <div
      className={`relative overflow-hidden ${
        isTop
          ? 'h-[24vh] min-h-[160px] max-h-[210px] border-b border-[#D9A441]/55'
          : 'h-full border-r border-[#D9A441]/55'
      }`}
    >
      {/* Gradient dasar: dark green -> emerald, + glow emas lembut di pojok */}
      <div className="absolute inset-0 bg-gradient-to-br from-primary-dark via-primary to-primary" />
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_75%_85%,_rgba(217,164,65,0.28),_transparent_60%)]" />
      <div className="absolute inset-0 opacity-20 bg-[radial-gradient(circle_at_25%_15%,_rgba(255,255,255,0.35),_transparent_50%)]" />

      {bgImageSrc ? (
        <>
          <img src={bgImageSrc} alt="" className="absolute inset-0 w-full h-full object-cover" />
          {/* Foto asli terang (siang/senja) - tint warna tema kuat supaya teks putih tetap kontras */}
          <div className="absolute inset-0 bg-gradient-to-b from-primary-dark/90 via-primary/80 to-primary-dark/90" />
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_75%_85%,_rgba(217,164,65,0.25),_transparent_60%)]" />
        </>
      ) : (
        <LoginHeroBackground pattern={heroPattern} />
      )}

      {/* Konten */}
      <div
        className={`relative z-10 flex flex-col items-center text-center h-full ${
          isTop ? 'justify-center px-6 py-3' : 'justify-center px-6 lg:px-10'
        }`}
      >
        <img
          src={loginIllustration}
          alt="Keluarga Besar Botanika Sriwedari"
          className={isTop ? 'w-14 mb-1 drop-shadow-lg' : 'w-32 lg:w-40 mb-5 drop-shadow-xl'}
        />
        <h1 className={isTop ? 'text-sm font-bold text-white tracking-tight' : 'text-xl lg:text-2xl font-bold text-white tracking-tight leading-tight'}>
          Manajemen Pengurus
        </h1>
        <h2 className={isTop ? 'text-[11px] font-semibold text-[#E9C877] mt-0.5' : 'text-sm lg:text-base font-semibold text-[#E9C877] mt-1'}>
          KBBS APP
        </h2>

        {!isTop && (
          <div className="flex items-center gap-3 mt-4">
            <span className="h-px w-8 bg-[#D9A441]/50" />
            <span className="w-1.5 h-1.5 rotate-45 border border-[#D9A441]/70" />
            <span className="h-px w-8 bg-[#D9A441]/50" />
          </div>
        )}

        {!isTop && (
          <p className="mt-4 text-[13px] lg:text-sm leading-relaxed text-white/75 max-w-[17rem]">
            Pantau kas, IPL dan komunikasi warga dalam satu portal.
          </p>
        )}
      </div>
    </div>
  );
};

export default BrandPanel;
