import { useEffect, useState } from "react";
import { API_BASE_URL } from "@/config/api";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import UserTable from "./UserTable";
import UserForm from "./UserForm";
import { AlertDialog, AlertDialogContent, AlertDialogHeader, AlertDialogFooter, AlertDialogTitle, AlertDialogCancel, AlertDialogAction } from "@/components/ui/alert-dialog";
import * as XLSX from "xlsx";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "@/components/ui/sonner";
import { useRolePermissions } from "@/hooks/useRolePermissions";


export default function UsersPage() {
  const [users, setUsers] = useState([]);
  const [search, setSearch] = useState("");
  const { token, logout, user } = useAuth(); // 🔥 AMBIL TOKEN & USER
  const { canCreate, canUpdate: canEdit, canDelete } = useRolePermissions(user?.role, token);

  // FORM
  const [openForm, setOpenForm] = useState(false);
  const [selectedUser, setSelectedUser] = useState(null);

  // MULTI SELECT
  const [selectedRows, setSelectedRows] = useState([]);

  // FILTER
  const [showFilter, setShowFilter] = useState(false);
  const [filterStatus, setFilterStatus] = useState("all");

  // TINDAKAN DROPDOWN
  const [actionOpen, setActionOpen] = useState(false);

  // BULK DELETE DIALOG
  const [openBulkDelete, setOpenBulkDelete] = useState(false);

  // PASSWORD MODALS
  const [openChangePassword, setOpenChangePassword] = useState(false);
  const [openSetPassword, setOpenSetPassword] = useState(false);
  const [passwordTarget, setPasswordTarget] = useState(null);
  const [passwordForm, setPasswordForm] = useState({
    oldPassword: "",
    newPassword: "",
    confirmPassword: ""
  });

  // pagination
  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(10);

  // FILTER STATUS WARGA
  const [filterRole, setFilterRole] = useState("all");



  const loadUsers = async () => {
  try {
    const res = await fetch(`${API_BASE_URL}/api/users`, {
      headers: {
        Authorization: `Bearer ${token}`, // 🔐 JWT
      },
    });

    if (res.status === 401) {
      logout(); // token invalid / expired
      return;
    }

    if (!res.ok) {
      throw new Error(`HTTP ${res.status}`);
    }

    let data = await res.json();
    
    console.log('👥 Loaded users:', data);
    console.log('👥 First user sample:', data[0]);
    
    // Filter untuk warga/karyawan - hanya lihat data sendiri
    if (user?.role === 'warga' || user?.role === 'karyawan') {
      data = data.filter(u => u.id === user.id);
    }
    
    setUsers(data);

  } catch (err) {
    console.error("Gagal load users", err);
    toast.error("Gagal memuat data pengguna");
  }
};


  useEffect(() => {
    if (token) {
      loadUsers();
    }
  }, [token]);

  // HANDLER: Ganti Kata Sandi (untuk diri sendiri)
  const handleChangePassword = async () => {
    if (!passwordForm.oldPassword || !passwordForm.newPassword || !passwordForm.confirmPassword) {
      toast.error("Semua field harus diisi");
      return;
    }
    if (passwordForm.newPassword !== passwordForm.confirmPassword) {
      toast.error("Password baru dan konfirmasi tidak cocok");
      return;
    }
    if (passwordForm.newPassword.length < 6) {
      toast.error("Password baru minimal 6 karakter");
      return;
    }

    try {
      const res = await fetch(`${API_BASE_URL}/api/users/change-password`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify({
          old_password: passwordForm.oldPassword,
          new_password: passwordForm.newPassword
        })
      });

      if (!res.ok) {
        const data = await res.json();
        toast.error(data.detail || "Gagal mengganti password");
        return;
      }

      const data = await res.json();
      toast.success("Password berhasil diubah");
      setOpenChangePassword(false);
      setPasswordForm({ oldPassword: "", newPassword: "", confirmPassword: "" });
    } catch (err) {
      console.error("Error changing password:", err);
      toast.error(err.message || "Tidak dapat terhubung ke server");
    }
  };

  // HANDLER: Set Password (untuk admin set password user lain)
  const handleSetPassword = async () => {
    if (!passwordForm.newPassword || !passwordForm.confirmPassword) {
      toast.error("Password harus diisi");
      return;
    }
    if (passwordForm.newPassword !== passwordForm.confirmPassword) {
      toast.error("Password dan konfirmasi tidak cocok");
      return;
    }
    if (passwordForm.newPassword.length < 6) {
      toast.error("Password minimal 6 karakter");
      return;
    }

    try {
      const res = await fetch(`${API_BASE_URL}/api/users/${passwordTarget.id}/set-password`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify({
          new_password: passwordForm.newPassword
        })
      });

      if (!res.ok) {
        const data = await res.json();
        toast.error(data.detail || "Gagal mengatur password");
        return;
      }

      const data = await res.json();
      toast.success(`Password untuk ${passwordTarget.fullname} berhasil diatur`);
      setOpenSetPassword(false);
      setPasswordForm({ oldPassword: "", newPassword: "", confirmPassword: "" });
      setPasswordTarget(null);
    } catch (err) {
      toast.error("Tidak dapat terhubung ke server");
    }
  };

  // HANDLER: Send WhatsApp Reset Link
  const handleSendResetLink = async (targetUser) => {
    console.log('🔍 handleSendResetLink called with:', targetUser);
    console.log('🔍 targetUser.id:', targetUser?.id);
    console.log('🔍 targetUser.whatsapp:', targetUser?.whatsapp);
    console.log('🔍 targetUser.fullname:', targetUser?.fullname);
    
    if (!targetUser || !targetUser.id) {
      toast.error("Data user tidak valid");
      console.error('❌ targetUser is invalid:', targetUser);
      return;
    }
    
    try {
      const url = `${API_BASE_URL}/api/users/${targetUser.id}/reset-password-link`;
      console.log('📤 Sending POST to:', url);
      
      const res = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`
        }
      });

      console.log('📥 Response status:', res.status);

      if (!res.ok) {
        const data = await res.json();
        console.log('📥 Error data:', data);
        toast.error(data.detail || "Gagal mengirim link");
        return;
      }

      const data = await res.json();
      console.log('📥 Response data:', data);

      toast.success(`Link reset password berhasil dikirim ke WhatsApp ${targetUser.whatsapp}`);
    } catch (err) {
      console.error('❌ Error sending reset link:', err);
      toast.error(`Tidak dapat terhubung ke server: ${err.message}`);
    }
  };

  // FILTER LOGIC
 const filtered = users
  .filter((u) =>
    u.username.toLowerCase().includes(search.toLowerCase())
  )
  .filter((u) => {
    if (filterStatus === "active") return u.status === "active";
    if (filterStatus === "inactive") return u.status === "inactive";
    return true;
  })
  .filter((u) => {
    if (filterRole === "warga") return u.role === "warga";
    if (filterRole === "karyawan") return u.role === "karyawan";
    if (filterRole === "admin") return u.role === "admin";
    return true;
  });


  // EXPORT EXCEL
  const exportExcel = () => {
    const worksheet = XLSX.utils.json_to_sheet(filtered);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Users");
    XLSX.writeFile(workbook, "users.xlsx");
  };

  // BULK DELETE
  const doBulkDelete = async () => {
    for (const id of selectedRows) {
      await fetch(`${API_BASE_URL}/api/users/${id}`, {
      method: "DELETE",
      headers: {
        Authorization: `Bearer ${token}`,
      },
  });

    }
    setSelectedRows([]);
    loadUsers();
    setOpenBulkDelete(false);
  };

        // -----------------------------
        // PAGINATION LOGIC
        // -----------------------------
        const totalItems = filtered.length;
        const totalPages = Math.ceil(totalItems / perPage);

        const startIndex = (page - 1) * perPage;
        const endIndex = Math.min(startIndex + perPage, totalItems);

        const paginated = filtered.slice(startIndex, endIndex);

        // memastikan page tidak melebihi total
        useEffect(() => {
            if (page > totalPages) setPage(totalPages || 1);
        }, [totalPages]);

  return (
    <div className="p-6 space-y-4">
      {/* HEADER */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold dark:text-gray-100">Pengguna</h1>
          <p className="text-sm text-gray-600 dark:text-gray-400">Kelola akun pengguna sistem</p>
        </div>
        {canCreate('users-list') && (
          <Button 
            onClick={() => { setSelectedUser(null); setOpenForm(true); }}
            className="bg-primary hover:bg-primary/90 text-white"
          >
            + Tambah User
          </Button>
        )}
      </div>

      {/* SEARCH & FILTER */}
      <div className="flex gap-3">
        <Input
          placeholder="Cari nama pengguna..."
          value={search}
          onChange={(e) => {
            setSearch(e.target.value);
            setPage(1);
          }}
          className="flex-1 dark:bg-gray-800 dark:text-gray-100 dark:border-gray-700"
        />
        <Button
          variant="outline"
          onClick={() => setShowFilter(!showFilter)}
          className="dark:border-gray-700 dark:text-gray-200"
        >
          Filter
        </Button>
      </div>

      {/* FILTER PANEL */}
      {showFilter && (
        <div className="bg-white dark:bg-gray-900 p-6 rounded-lg border dark:border-gray-700 space-y-4">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {/* STATUS AKTIF */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Status Aktif</label>
              <select 
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-gray-50"
                value={filterStatus}
                onChange={(e) => {
                  setFilterStatus(e.target.value);
                  setPage(1);
                }}
              >
                <option value="all">Semua</option>
                <option value="active">Aktif</option>
                <option value="inactive">Tidak Aktif</option>
              </select>
            </div>

            {/* STATUS WARGA */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Status Warga</label>
              <select
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-gray-50"
                value={filterRole}
                onChange={(e) => {
                  setFilterRole(e.target.value);
                  setPage(1);
                }}
              >
                <option value="all">Semua</option>
                <option value="warga">Warga</option>
                <option value="karyawan">Karyawan</option>
                <option value="admin">Admin</option>
              </select>
            </div>

            {/* PER HALAMAN */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Per Halaman</label>
              <select
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-gray-50"
                value={perPage}
                onChange={(e) => {
                  setPerPage(Number(e.target.value));
                  setPage(1);
                }}
              >
                <option value="5">5</option>
                <option value="10">10</option>
                <option value="25">25</option>
                <option value="50">50</option>
                <option value="100">100</option>
              </select>
            </div>
          </div>
        </div>
      )}

      {/* ACTIONS */}
      {selectedRows.length > 0 && canDelete('users-list') && (
        <div className="flex gap-3 bg-blue-50 dark:bg-blue-900/20 p-4 rounded-lg border border-blue-200 dark:border-blue-800">
          <span className="text-sm dark:text-gray-300">
            {selectedRows.length} item dipilih
          </span>
          <Button
            size="sm"
            onClick={exportExcel}
            className="bg-green-500 hover:bg-green-600 text-white"
          >
            Export Excel
          </Button>
        </div>
      )}

      {/* TABLE */}
       <UserTable
        data={paginated}
        onEdit={(user) => {
          setSelectedUser(user);
          setOpenForm(true);
        }}
        onDelete={loadUsers}
        selectedRows={selectedRows}
        setSelectedRows={setSelectedRows}
        onSetPassword={(targetUser) => {
          setPasswordTarget(targetUser);
          setOpenSetPassword(true);
        }}
        onResetPassword={handleSendResetLink}
      />

 {/* PAGINATION — mirip screenshot */}
      <div className="flex justify-between items-center text-sm text-gray-600 dark:text-gray-300 mt-2">

        <span>
          {totalItems === 0
            ? "0 data"
            : `${startIndex + 1}-${endIndex} dari ${totalItems}`}
        </span>

        <div className="flex gap-2">
          <Button
            variant="outline"
            disabled={page === 1}
            onClick={() => setPage(page - 1)}
          >
            Sebelumnya
          </Button>

          <Button
            variant="outline"
            disabled={page === totalPages}
            onClick={() => setPage(page + 1)}
          >
            Selanjutnya
          </Button>
        </div>
      </div>


      {/* FORM ADD/EDIT */}
      <UserForm
        open={openForm}
        onOpenChange={setOpenForm}
        user={selectedUser}
        onSaved={loadUsers}
      />

      {/* BULK DELETE CONFIRMATION */}
      <AlertDialog open={openBulkDelete} onOpenChange={setOpenBulkDelete}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              Hapus {selectedRows.length} user terpilih?
            </AlertDialogTitle>
          </AlertDialogHeader>

          <AlertDialogFooter>
            <AlertDialogCancel>Batal</AlertDialogCancel>

            <AlertDialogAction
              className="bg-red-600 hover:bg-red-700 text-white"
              onClick={doBulkDelete}
            >
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* GANTI PASSWORD MODAL (untuk diri sendiri) */}
      <Dialog open={openChangePassword} onOpenChange={setOpenChangePassword}>
        <DialogContent className="dark:bg-gray-900 dark:text-gray-100">
          <DialogHeader>
            <DialogTitle>Ganti Kata Sandi</DialogTitle>
          </DialogHeader>
          
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="oldPassword">Kata Sandi Lama</Label>
              <Input
                id="oldPassword"
                type="password"
                placeholder="Kata Sandi Lama"
                value={passwordForm.oldPassword}
                onChange={(e) => setPasswordForm({ ...passwordForm, oldPassword: e.target.value })}
                className="dark:bg-gray-800"
              />
            </div>
            
            <div className="space-y-2">
              <Label htmlFor="newPassword">Kata Sandi Baru</Label>
              <Input
                id="newPassword"
                type="password"
                placeholder="Kata Sandi Baru"
                value={passwordForm.newPassword}
                onChange={(e) => setPasswordForm({ ...passwordForm, newPassword: e.target.value })}
                className="dark:bg-gray-800"
              />
            </div>
            
            <div className="space-y-2">
              <Label htmlFor="confirmPassword">Ulangi Kata Sandi</Label>
              <Input
                id="confirmPassword"
                type="password"
                placeholder="Ulangi Kata Sandi"
                value={passwordForm.confirmPassword}
                onChange={(e) => setPasswordForm({ ...passwordForm, confirmPassword: e.target.value })}
                className="dark:bg-gray-800"
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setOpenChangePassword(false)}>
              Batal
            </Button>
            <Button onClick={handleChangePassword}>
              Simpan
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* SET PASSWORD MODAL (untuk admin set password user lain) */}
      <Dialog open={openSetPassword} onOpenChange={setOpenSetPassword}>
        <DialogContent className="dark:bg-gray-900 dark:text-gray-100">
          <DialogHeader>
            <DialogTitle>
              Setel Kata Sandi - {passwordTarget?.fullname}
            </DialogTitle>
          </DialogHeader>
          
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="setNewPassword">Kata Sandi Baru</Label>
              <Input
                id="setNewPassword"
                type="password"
                placeholder="Kata Sandi Baru"
                value={passwordForm.newPassword}
                onChange={(e) => setPasswordForm({ ...passwordForm, newPassword: e.target.value })}
                className="dark:bg-gray-800"
              />
            </div>
            
            <div className="space-y-2">
              <Label htmlFor="setConfirmPassword">Ulangi Kata Sandi</Label>
              <Input
                id="setConfirmPassword"
                type="password"
                placeholder="Ulangi Kata Sandi"
                value={passwordForm.confirmPassword}
                onChange={(e) => setPasswordForm({ ...passwordForm, confirmPassword: e.target.value })}
                className="dark:bg-gray-800"
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => {
              setOpenSetPassword(false);
              setPasswordForm({ oldPassword: "", newPassword: "", confirmPassword: "" });
            }}>
              Batal
            </Button>
            <Button onClick={handleSetPassword}>
              Setel Password
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

    </div>
  );
}
